// site/src/english/data/reading/b1-engineering.ts
// B1 engineering-stream reading texts. Bilingual; inline-glossed; targetWords -> vocabB1 ids.
import type { ReadingUnit } from "~/english/types";

export const b1Engineering: ReadingUnit[] = [
  {"id":"b1e-pr-tradeoff","level":"B1","stream":"engineering","title":{"en":"Code Review: Caching Strategy Debate","ru":"Ревью кода: спор о стратегии кэширования"},"blurb":{"en":"A pull-request thread where a reviewer and an author discuss the tradeoffs of adding a cache layer to a user-profile service.","ru":"Обсуждение в пул-реквесте: ревьюер и автор взвешивают плюсы и минусы добавления слоя кэша в сервис профилей пользователей."},"source":{"en":"Pull-request review discussion","ru":"Обсуждение в пул-реквесте"},"passages":[{"en":"**PR #412 — Add in-memory cache to UserProfileService**\n\n**Reviewer (Lena):** Thanks for the PR. The idea makes sense — the profile endpoint is called on every page load, so reducing database hits is a reasonable goal. However, I have a concern about the cache invalidation strategy. Right now the code sets a fixed TTL of 60 seconds, but it does not clear the cache when a user updates their profile. This means a user could see stale data for up to a minute after saving changes. Is that acceptable?","ru":"**PR #412 — Добавить кэш в памяти в UserProfileService**\n\n**Ревьюер (Лена):** Спасибо за PR. Идея разумная — эндпоинт профиля вызывается при каждой загрузке страницы, поэтому снижение нагрузки на базу данных — вполне обоснованная цель. Однако меня беспокоит стратегия инвалидации кэша. Сейчас в коде задан фиксированный TTL в 60 секунд, но кэш не очищается, когда пользователь обновляет свой профиль. Это значит, что пользователь может видеть устаревшие данные до минуты после сохранения изменений. Это приемлемо?","words":[{"id":"b1e-pr-tradeoff-w1","w":"in-memory cache","ru":"кэш в памяти","gloss":"a storage layer that keeps data in RAM so it can be read very quickly, without going to a database","pos":"phrase","example":"An in-memory cache can serve a response in under one millisecond."},{"id":"b1e-pr-tradeoff-w2","w":"TTL","ru":"TTL (время жизни)","gloss":"Time To Live — the number of seconds a cached item is kept before it is deleted automatically","pos":"abbr","ipa":"tiː tiː el","example":"Setting a TTL of 300 seconds means the cache refreshes every five minutes."},{"id":"b1e-pr-tradeoff-w3","w":"stale data","ru":"устаревшие данные","gloss":"data that is out of date because it has not been updated after the source changed","pos":"phrase","example":"If the cache is not cleared on write, users may receive stale data."},{"id":"b1e-pr-tradeoff-w4","w":"strategy","ru":"стратегия","gloss":"a plan for how to handle a repeated situation — here, how to decide when to clear cached data","pos":"noun","ipa":"ˈstrætədʒi","example":"The team chose a write-through strategy to keep the cache consistent."}]},{"en":"**Author (Dmitri):** Good point. My thinking was that profile data rarely changes, so a 60-second delay is acceptable for most users. The main goal was to reduce database load during peak hours. I could add a cache-invalidation call in the update handler, but that would add more complexity to the service. What do you think — is it worth the extra code?","ru":"**Автор (Дмитрий):** Справедливое замечание. Я исходил из того, что данные профиля меняются редко, поэтому задержка в 60 секунд приемлема для большинства пользователей. Главная цель — снизить нагрузку на базу данных в часы пик. Я мог бы добавить вызов инвалидации кэша в обработчик обновлений, но это усложнит сервис. Как считаешь — стоит ли оно того?","words":[{"id":"b1e-pr-tradeoff-w5","w":"peak hours","ru":"часы пик","gloss":"the times of day when the system receives the most traffic or requests","pos":"phrase","example":"The service handles ten times more requests during peak hours."},{"id":"b1e-pr-tradeoff-w6","w":"cache-invalidation","ru":"инвалидация кэша","gloss":"the process of removing or marking cached data as outdated so the next read fetches fresh data","pos":"phrase","example":"Cache-invalidation is often called one of the two hard problems in computer science."}]},{"en":"**Reviewer (Lena):** I think it is worth it, yes. Here is why: profile updates are rare, but when they happen the user expects to see the change immediately. If they update their display name and still see the old one, they will think the save failed. That is a bad experience. The extra code is small — you only need to call `cache.delete(userId)` at the end of the update method. This is the write-invalidate option, and it is the simplest approach that keeps data consistent.","ru":"**Ревьюер (Лена):** Думаю, да, стоит. Вот почему: обновления профиля случаются редко, но когда это происходит, пользователь ожидает увидеть изменения немедленно. Если он обновил отображаемое имя и по-прежнему видит старое, он решит, что сохранение не сработало. Это плохой опыт. Дополнительный код небольшой — нужно лишь вызвать `cache.delete(userId)` в конце метода обновления. Это подход с инвалидацией на запись — самый простой способ обеспечить согласованность данных.","words":[{"id":"b1e-pr-tradeoff-w7","w":"option","ru":"вариант; опция","gloss":"one of several possible choices or ways to do something","pos":"noun","ipa":"ˈɒpʃən","example":"We have two options: fix the bug now or add a workaround until the next release."},{"id":"b1e-pr-tradeoff-w8","w":"consistent","ru":"согласованный; непротиворечивый","gloss":"always the same; not having differences between copies of the same data","pos":"adj","ipa":"kənˈsɪstənt","example":"A consistent cache shows the same data as the database at all times."}]},{"en":"**Author (Dmitri):** That makes sense. I will add the invalidation call. One more question: should I also block read requests while the cache is being refreshed, to avoid a thundering herd? For example, if ten requests arrive at the same time after the cache expires, they could all hit the database at once.","ru":"**Автор (Дмитрий):** Понял, логично. Добавлю вызов инвалидации. Ещё один вопрос: стоит ли блокировать запросы на чтение, пока кэш обновляется, чтобы избежать проблемы «громового стада»? Например, если после истечения кэша одновременно придут десять запросов, все они могут одновременно обратиться к базе данных.","words":[{"id":"b1e-pr-tradeoff-w9","w":"block","ru":"блокировать","gloss":"to stop or delay something from happening — here, to make other requests wait","pos":"verb","ipa":"blɒk","example":"A mutex can block concurrent threads until the first one finishes."},{"id":"b1e-pr-tradeoff-w10","w":"thundering herd","ru":"«громовое стадо»","gloss":"a situation where many processes or requests all try to access the same resource at the same moment, overloading it","pos":"phrase","example":"To prevent a thundering herd, only the first request should fetch fresh data while others wait."}]},{"en":"**Reviewer (Lena):** Good thinking. For this service the risk is low — user profiles are not requested that frequently. I would not block requests now; it adds complexity and the problem only appears under very high traffic. Instead, keep it simple and maintain the current approach: let all requests through, and if the thundering herd ever becomes a real issue, we can add a request-coalescing layer at that point. Overall the PR looks good. Please update the invalidation logic and request a re-review.","ru":"**Ревьюер (Лена):** Хорошее замечание. Для данного сервиса риск невелик — профили пользователей запрашиваются не так часто. Я бы пока не блокировала запросы: это усложняет код, а проблема возникает только при очень высоком трафике. Лучше сохранить простоту и поддерживать текущий подход: пропускать все запросы, а если «громовое стадо» когда-нибудь станет реальной проблемой — добавим слой объединения запросов тогда. В целом PR выглядит хорошо. Пожалуйста, обнови логику инвалидации и запроси повторное ревью.","words":[{"id":"b1e-pr-tradeoff-w11","w":"maintain","ru":"поддерживать; сохранять","gloss":"to keep something in its current state, or to continue doing something","pos":"verb","ipa":"meɪnˈteɪn","example":"It is easier to maintain a simple design than a complex one."},{"id":"b1e-pr-tradeoff-w12","w":"request-coalescing","ru":"объединение запросов","gloss":"a technique where multiple identical requests are merged into one, so the backend is only called once","pos":"phrase","example":"Request-coalescing reduces database load when many users ask for the same data simultaneously."}]}],"phrases":[{"id":"b1e-pr-tradeoff-p1","en":"Is that acceptable?","ru":"Это приемлемо?","note":{"en":"A polite way to ask whether a tradeoff or limitation is okay with the team.","ru":"Вежливый способ спросить, устраивает ли команду компромисс или ограничение."}},{"id":"b1e-pr-tradeoff-p2","en":"Is it worth the extra code?","ru":"Стоит ли это дополнительного кода?","note":{"en":"Engineers often weigh benefit against complexity using this phrase.","ru":"Инженеры часто взвешивают пользу и сложность, используя это выражение."}},{"id":"b1e-pr-tradeoff-p3","en":"keep it simple","ru":"не усложнять","note":{"en":"A common recommendation to prefer a straightforward solution over a clever but complex one.","ru":"Распространённая рекомендация предпочитать простое решение сложному, но изощрённому."}},{"id":"b1e-pr-tradeoff-p4","en":"request a re-review","ru":"запросить повторное ревью","note":{"en":"After making changes, the author asks the reviewer to look at the code again.","ru":"После внесения правок автор просит ревьюера снова посмотреть код."}}],"questions":[{"id":"b1e-pr-tradeoff-q1","q":{"en":"What is Lena's main concern about the current caching code?","ru":"В чём состоит главная претензия Лены к текущему коду кэширования?"},"options":[{"en":"The TTL is too long and wastes memory.","ru":"TTL слишком большой и расходует лишнюю память."},{"en":"The cache is not cleared when a user updates their profile, so they may see old data.","ru":"Кэш не очищается при обновлении профиля, поэтому пользователь может видеть старые данные."},{"en":"The cache layer adds too much complexity to the service.","ru":"Слой кэша слишком усложняет сервис."}],"answer":1,"explain":{"en":"Lena writes that the code does not clear the cache on profile update, meaning users could see stale data for up to a minute.","ru":"Лена пишет, что код не очищает кэш при обновлении профиля, а значит, пользователь может видеть устаревшие данные до минуты."}},{"id":"b1e-pr-tradeoff-q2","q":{"en":"What simple fix does Lena suggest to keep the cache consistent?","ru":"Какое простое исправление предлагает Лена, чтобы обеспечить согласованность кэша?"},"options":[{"en":"Reduce the TTL from 60 seconds to 5 seconds.","ru":"Сократить TTL с 60 секунд до 5 секунд."},{"en":"Block all read requests while the cache refreshes.","ru":"Блокировать все запросы на чтение, пока кэш обновляется."},{"en":"Call cache.delete(userId) at the end of the update method.","ru":"Вызывать cache.delete(userId) в конце метода обновления."}],"answer":2,"explain":{"en":"Lena says the fix is small: call cache.delete(userId) in the update handler. This is the write-invalidate option.","ru":"Лена говорит, что исправление небольшое: вызвать cache.delete(userId) в обработчике обновлений. Это подход write-invalidate."}},{"id":"b1e-pr-tradeoff-q3","q":{"en":"Why does Lena recommend NOT adding request-blocking against the thundering herd right now?","ru":"Почему Лена рекомендует сейчас НЕ добавлять блокировку запросов против «громового стада»?"},"options":[{"en":"Profile updates are too frequent for blocking to help.","ru":"Обновления профиля происходят слишком часто, чтобы блокировка помогла."},{"en":"The risk is low for this service, and blocking adds unnecessary complexity.","ru":"Для данного сервиса риск невелик, а блокировка добавляет лишнюю сложность."},{"en":"The database can easily handle all concurrent requests.","ru":"База данных легко справляется со всеми параллельными запросами."}],"answer":1,"explain":{"en":"Lena explains that profile requests are not frequent enough to make the thundering herd a real problem, so the extra complexity is not worth it yet.","ru":"Лена объясняет, что профили запрашиваются недостаточно часто, чтобы «громовое стадо» стало реальной проблемой, поэтому дополнительная сложность пока не оправдана."}},{"id":"b1e-pr-tradeoff-q4","q":{"en":"What does Dmitri mean when he says profile data 'rarely changes'?","ru":"Что имеет в виду Дмитрий, говоря, что данные профиля «меняются редко»?"},"options":[{"en":"Users do not read their profiles very often.","ru":"Пользователи редко просматривают свои профили."},{"en":"Users update their profile information infrequently, so a short delay in seeing new data is usually acceptable.","ru":"Пользователи редко обновляют информацию в профиле, поэтому небольшая задержка в отображении новых данных обычно приемлема."},{"en":"The database schema for profiles is never modified.","ru":"Схема базы данных для профилей никогда не изменяется."}],"answer":1,"explain":{"en":"Dmitri's argument is that because users seldom change their profile, a 60-second stale window is an acceptable tradeoff for lower database load.","ru":"Аргумент Дмитрия: поскольку пользователи редко меняют профиль, окно устаревания в 60 секунд — приемлемый компромисс ради снижения нагрузки на БД."}}],"targetWords":["ngsl:0838","ngsl:0859","ngsl:1018","ngsl:0942"]},
  {"id":"b1e-rfc-excerpt","level":"B1","stream":"engineering","title":{"en":"RFC: Replace Polling with WebSockets","ru":"RFC: заменить поллинг на WebSockets"},"blurb":{"en":"An excerpt from a technical design document proposing to switch a notification system from HTTP polling to a persistent WebSocket connection.","ru":"Фрагмент технического проектного документа с предложением перевести систему уведомлений с HTTP-поллинга на постоянное WebSocket-соединение."},"source":{"en":"RFC / design document excerpt","ru":"Фрагмент RFC / проектного документа"},"passages":[{"en":"**RFC-019: Replace HTTP Polling with WebSockets in the Notification Service**\n\n**Status:** Under review\n**Author:** Platform Team\n\n**Summary**\n\nThis document proposes replacing the current HTTP polling mechanism in the notification service with a persistent WebSocket connection. The goal is to reduce unnecessary network traffic and improve the responsiveness of real-time alerts for end users.","ru":"**RFC-019: Замена HTTP-поллинга на WebSockets в сервисе уведомлений**\n\n**Статус:** На рассмотрении\n**Автор:** Команда платформы\n\n**Краткое содержание**\n\nДанный документ предлагает заменить текущий механизм HTTP-поллинга в сервисе уведомлений на постоянное WebSocket-соединение. Цель — сократить лишний сетевой трафик и повысить отзывчивость уведомлений в реальном времени для конечных пользователей.","words":[{"id":"b1e-rfc-excerpt-w1","w":"RFC","ru":"RFC (запрос на изменение)","gloss":"Request For Comments — an internal document that proposes a technical change and asks the team to discuss and approve it","pos":"abbr","ipa":"ɑːr ef siː","example":"The team published an RFC before starting the database migration."},{"id":"b1e-rfc-excerpt-w2","w":"propose","ru":"предлагать","gloss":"to formally suggest a plan or idea for others to consider","pos":"verb","ipa":"prəˈpəʊz","example":"The RFC proposes a new authentication flow for mobile clients."},{"id":"b1e-rfc-excerpt-w3","w":"polling","ru":"поллинг","gloss":"a method where the client repeatedly sends requests to the server at fixed intervals to check for new data","pos":"noun","ipa":"ˈpəʊlɪŋ","example":"Polling every second creates high load even when there is nothing new to fetch."},{"id":"b1e-rfc-excerpt-w4","w":"persistent connection","ru":"постоянное соединение","gloss":"a network connection that stays open continuously instead of being opened and closed for each request","pos":"phrase","example":"A persistent connection lets the server push data to the client without waiting for a new request."}]},{"en":"**Problem Statement**\n\nThe notification service currently uses HTTP polling: the client sends a GET request every three seconds to ask the server for new notifications. This approach has two significant problems. First, it creates a large volume of requests even when there are no new notifications to deliver. In a system with 50,000 active users, this produces roughly 1,000 requests per second at all times. Second, there is a delay of up to three seconds between when a notification is created and when the user sees it.","ru":"**Описание проблемы**\n\nСервис уведомлений в настоящее время использует HTTP-поллинг: клиент отправляет GET-запрос каждые три секунды, чтобы запросить у сервера новые уведомления. У этого подхода есть две существенные проблемы. Во-первых, он создаёт большой объём запросов, даже когда новых уведомлений нет. В системе с 50 000 активных пользователей это постоянно генерирует около 1 000 запросов в секунду. Во-вторых, между созданием уведомления и его отображением у пользователя есть задержка до трёх секунд.","words":[{"id":"b1e-rfc-excerpt-w5","w":"version","ru":"версия","gloss":"a particular form of something that is different from earlier or later forms","pos":"noun","ipa":"ˈvɜːʃən","example":"Version 2 of the API removes the polling endpoint entirely."},{"id":"b1e-rfc-excerpt-w6","w":"volume","ru":"объём","gloss":"the total amount or quantity of something — here, the number of network requests","pos":"noun","ipa":"ˈvɒljuːm","example":"A high volume of requests can overload the server during peak hours."}]},{"en":"**Proposed Solution**\n\nWe propose replacing polling with a WebSocket connection. When the user opens the application, the client establishes a single, long-lived WebSocket connection to the notification server. The server then pushes new notifications to the client immediately when they are available. The client does not need to ask repeatedly. This approach removes the constant background traffic and reduces notification latency from up to three seconds to under 100 milliseconds.","ru":"**Предлагаемое решение**\n\nМы предлагаем заменить поллинг WebSocket-соединением. Когда пользователь открывает приложение, клиент устанавливает одно долгоживущее WebSocket-соединение с сервером уведомлений. Затем сервер немедленно отправляет клиенту новые уведомления, как только они появляются. Клиенту не нужно делать повторные запросы. Такой подход устраняет постоянный фоновый трафик и сокращает задержку уведомлений с трёх секунд до менее 100 миллисекунд.","words":[{"id":"b1e-rfc-excerpt-w7","w":"replace","ru":"заменять","gloss":"to remove something and put a different thing in its place","pos":"verb","ipa":"rɪˈpleɪs","example":"The team plans to replace the REST endpoint with a GraphQL API."},{"id":"b1e-rfc-excerpt-w8","w":"long-lived","ru":"долгоживущий","gloss":"staying open or active for a long period of time rather than being closed quickly","pos":"adj","example":"A long-lived connection is efficient because it avoids the overhead of reconnecting."},{"id":"b1e-rfc-excerpt-w9","w":"latency","ru":"задержка","gloss":"the time delay between sending a request or event and receiving the response or result","pos":"noun","ipa":"ˈleɪtənsi","example":"High latency makes a chat application feel slow and unresponsive."}]},{"en":"**Tradeoffs and Risks**\n\nWebSockets are more complex to operate than simple HTTP endpoints. Each open connection uses server memory, so we need to plan capacity carefully. With 50,000 concurrent users, we estimate a need for roughly 5 GB of additional RAM across the notification service fleet. We also prefer to keep the old polling endpoint available for at least one version after the WebSocket launch, so that older clients can continue to work during the transition period.","ru":"**Компромиссы и риски**\n\nWebSockets сложнее в эксплуатации, чем простые HTTP-эндпоинты. Каждое открытое соединение использует память сервера, поэтому нам необходимо тщательно планировать мощности. При 50 000 одновременных пользователей мы оцениваем потребность примерно в 5 ГБ дополнительной оперативной памяти в рамках кластера сервиса уведомлений. Мы также предпочитаем сохранить старый поллинг-эндпоинт доступным хотя бы на одну версию после запуска WebSocket, чтобы старые клиенты могли продолжать работать в переходный период.","words":[{"id":"b1e-rfc-excerpt-w10","w":"prefer","ru":"предпочитать","gloss":"to like or choose one thing more than another","pos":"verb","ipa":"prɪˈfɜː","example":"We prefer a gradual rollout to reduce the risk of a wide outage."},{"id":"b1e-rfc-excerpt-w11","w":"concurrent users","ru":"одновременные пользователи","gloss":"the number of users who are using the system at exactly the same moment","pos":"phrase","example":"The load test simulated 100,000 concurrent users to find the system's breaking point."},{"id":"b1e-rfc-excerpt-w12","w":"transition period","ru":"переходный период","gloss":"the time during which a system moves from one state or version to another","pos":"phrase","example":"During the transition period, both the old and new APIs must remain available."}]},{"en":"**Decision Needed**\n\nThe platform team asks all stakeholders to review this RFC and leave comments by Friday. If there are no major objections, we will remove the polling mechanism in the next quarterly release and make WebSockets the only supported connection method. Please indicate your approval or concerns in the comments below.","ru":"**Требуется решение**\n\nКоманда платформы просит всех заинтересованных лиц ознакомиться с этим RFC и оставить комментарии до пятницы. Если серьёзных возражений не поступит, в следующем квартальном релизе мы удалим механизм поллинга и сделаем WebSockets единственным поддерживаемым способом подключения. Пожалуйста, укажите своё согласие или опасения в комментариях ниже.","words":[{"id":"b1e-rfc-excerpt-w13","w":"remove","ru":"удалять; убирать","gloss":"to take something away so it no longer exists in the system","pos":"verb","ipa":"rɪˈmuːv","example":"We will remove the deprecated endpoint in version 4.0."},{"id":"b1e-rfc-excerpt-w14","w":"stakeholders","ru":"заинтересованные стороны","gloss":"all the people or teams who are affected by or have an interest in a decision","pos":"noun","ipa":"ˈsteɪkhəʊldəz","example":"The RFC was shared with all stakeholders before the final decision was made."}]}],"phrases":[{"id":"b1e-rfc-excerpt-p1","en":"under review","ru":"на рассмотрении","note":{"en":"A document status meaning it has been submitted and people are reading and discussing it, but no decision has been made yet.","ru":"Статус документа, означающий, что он подан и люди читают и обсуждают его, но решение ещё не принято."}},{"id":"b1e-rfc-excerpt-p2","en":"no major objections","ru":"нет серьёзных возражений","note":{"en":"A phrase used in team decisions meaning that nobody has raised an important reason to stop the plan.","ru":"Фраза, используемая при командных решениях: никто не выдвинул веской причины остановить план."}},{"id":"b1e-rfc-excerpt-p3","en":"indicate your approval","ru":"выразить своё согласие","note":{"en":"To formally show that you agree with a proposal, often by leaving a comment or clicking an approve button.","ru":"Официально показать, что вы согласны с предложением — часто оставив комментарий или нажав кнопку «Approve»."}},{"id":"b1e-rfc-excerpt-p4","en":"plan capacity carefully","ru":"тщательно планировать мощности","note":{"en":"To calculate how much CPU, memory, or bandwidth a system will need before it is deployed.","ru":"Рассчитать, сколько процессорных ресурсов, памяти или полосы пропускания потребует система, до её развёртывания."}}],"questions":[{"id":"b1e-rfc-excerpt-q1","q":{"en":"What is the main problem with the current polling approach?","ru":"В чём главная проблема текущего подхода с поллингом?"},"options":[{"en":"It uses WebSockets, which are difficult to scale.","ru":"Он использует WebSockets, которые сложно масштабировать."},{"en":"It creates a large number of requests even when there are no new notifications, and adds a delay of up to three seconds.","ru":"Он создаёт большое количество запросов, даже когда нет новых уведомлений, и добавляет задержку до трёх секунд."},{"en":"It requires too much server memory for open connections.","ru":"Он требует слишком много памяти сервера для открытых соединений."}],"answer":1,"explain":{"en":"The RFC states two problems with polling: it produces roughly 1,000 requests per second with 50,000 users even when nothing is new, and there is up to a three-second notification delay.","ru":"В RFC указаны две проблемы поллинга: он генерирует около 1000 запросов в секунду при 50 000 пользователях даже когда ничего нового нет, плюс задержка уведомлений до трёх секунд."}},{"id":"b1e-rfc-excerpt-q2","q":{"en":"According to the RFC, how does the WebSocket approach reduce notification delay?","ru":"Как, согласно RFC, WebSocket-подход сокращает задержку уведомлений?"},"options":[{"en":"The client sends requests every half-second instead of every three seconds.","ru":"Клиент отправляет запросы каждые полсекунды вместо каждых трёх секунд."},{"en":"The server pushes notifications to the client immediately when they are available, without waiting for a request.","ru":"Сервер немедленно отправляет уведомления клиенту, как только они появляются, не ожидая запроса."},{"en":"Notifications are batched and delivered once per minute to reduce load.","ru":"Уведомления группируются и доставляются раз в минуту, чтобы снизить нагрузку."}],"answer":1,"explain":{"en":"With WebSockets, the server pushes data immediately. The client does not need to ask repeatedly, which cuts latency from up to 3 seconds to under 100 ms.","ru":"С WebSockets сервер сразу отправляет данные. Клиенту не нужно делать повторные запросы, что сокращает задержку с трёх секунд до менее 100 мс."}},{"id":"b1e-rfc-excerpt-q3","q":{"en":"Why does the team want to keep the old polling endpoint available for one more version?","ru":"Почему команда хочет сохранить старый поллинг-эндпоинт ещё на одну версию?"},"options":[{"en":"So they can compare the performance of both approaches in production.","ru":"Чтобы сравнить производительность обоих подходов в продакшене."},{"en":"Because the WebSocket implementation is not ready yet.","ru":"Потому что реализация WebSocket ещё не готова."},{"en":"So that older clients can continue to work during the transition period.","ru":"Чтобы старые клиенты могли продолжать работать в переходный период."}],"answer":2,"explain":{"en":"The RFC says they prefer to keep the old endpoint for at least one version so older clients are not broken immediately.","ru":"В RFC говорится, что они предпочитают сохранять старый эндпоинт хотя бы на одну версию, чтобы старые клиенты не сломались сразу."}},{"id":"b1e-rfc-excerpt-q4","q":{"en":"What does the RFC say about memory usage with WebSockets?","ru":"Что говорит RFC об использовании памяти при WebSockets?"},"options":[{"en":"WebSockets use less memory than polling because there are fewer requests.","ru":"WebSockets используют меньше памяти, чем поллинг, потому что запросов меньше."},{"en":"Each open WebSocket connection uses server memory, requiring around 5 GB of extra RAM for 50,000 users.","ru":"Каждое открытое WebSocket-соединение использует память сервера, что требует около 5 ГБ дополнительной оперативной памяти для 50 000 пользователей."},{"en":"Memory usage is not a concern because connections are short-lived.","ru":"Использование памяти не является проблемой, поскольку соединения краткосрочные."}],"answer":1,"explain":{"en":"The RFC notes that each open connection uses server memory and estimates roughly 5 GB of additional RAM is needed for 50,000 concurrent users.","ru":"В RFC отмечается, что каждое открытое соединение использует память сервера, и оценивается потребность примерно в 5 ГБ дополнительной RAM для 50 000 одновременных пользователей."}}],"targetWords":["ngsl:0876","ngsl:0992","ngsl:0948","ngsl:1051","ngsl:0979"]},
  {"id":"b1e-postmortem","level":"B1","stream":"engineering","title":{"en":"Postmortem: Payment Service Outage","ru":"Постмортем: сбой платёжного сервиса"},"blurb":{"en":"A blameless postmortem written after a 35-minute payment service outage caused by a misconfigured database connection pool.","ru":"Бесстрастный постмортем, написанный после 35-минутного сбоя платёжного сервиса из-за неправильно настроенного пула соединений с базой данных."},"source":{"en":"Internal incident report","ru":"Внутренний отчёт об инциденте"},"passages":[{"en":"**Incident Summary**\n\nOn Thursday, 2026-05-14, the payment service was unavailable for 35 minutes between 14:07 and 14:42 UTC. During this time, all checkout requests failed with a 503 error. Approximately 1,200 transactions were rejected, and the estimated revenue impact was $4,800. No customer data was lost.","ru":"**Краткое описание инцидента**\n\nВ четверг, 14 мая 2026 года, платёжный сервис был недоступен 35 минут — с 14:07 до 14:42 UTC. За это время все запросы на оформление заказа завершались с ошибкой 503. Было отклонено около 1 200 транзакций, предполагаемые потери выручки составили 4 800 долларов. Данные клиентов не пострадали.","words":[{"id":"b1e-postmortem-w1","w":"outage","ru":"сбой, простой","gloss":"a period when a service is not working and users cannot use it","pos":"noun","ipa":"ˈaʊtɪdʒ","example":"The outage lasted two hours before the team restored the service."},{"id":"b1e-postmortem-w2","w":"503 error","ru":"ошибка 503","gloss":"an HTTP status code meaning the server is temporarily unable to handle the request — usually because it is overloaded or down","pos":"phrase","example":"Users saw a 503 error because all backend workers were busy."},{"id":"b1e-postmortem-w3","w":"transaction","ru":"транзакция","gloss":"a single complete operation, such as one payment or one database write, that either fully succeeds or fully fails","pos":"noun","ipa":"trænˈzækʃən","example":"Each transaction is recorded in the audit log with a unique ID."},{"id":"b1e-postmortem-w4","w":"revenue impact","ru":"потери выручки","gloss":"the amount of money a company loses or fails to earn because of a problem","pos":"phrase","example":"The team calculated the revenue impact by counting failed orders during the outage."}]},{"en":"**Root Cause**\n\nA configuration change was deployed to production at 14:05 UTC as part of a routine database migration. The new config set the connection pool size to 2 instead of 20. As a result, the service ran out of available database connections almost immediately under normal traffic. Requests began to queue and then time out, causing the 503 errors.","ru":"**Первопричина**\n\nВ 14:05 UTC в продакшен было развёрнуто изменение конфигурации в рамках плановой миграции базы данных. В новом конфиге размер пула соединений был задан равным 2 вместо 20. В результате сервис практически сразу исчерпал доступные соединения с базой данных при обычном трафике. Запросы начали накапливаться в очереди, затем истекало время ожидания — это и вызывало ошибки 503.","words":[{"id":"b1e-postmortem-w5","w":"root cause","ru":"первопричина","gloss":"the deepest, original reason why a problem happened — fixing it prevents the problem from happening again","pos":"phrase","example":"The root cause was a missing index, not the slow query itself."},{"id":"b1e-postmortem-w6","w":"connection pool","ru":"пул соединений","gloss":"a set of database connections that are kept open and shared between requests to avoid the cost of opening a new connection each time","pos":"phrase","example":"Setting the connection pool to 2 was too low for production traffic."},{"id":"b1e-postmortem-w7","w":"time out","ru":"истекать по таймауту","gloss":"to fail because the allowed waiting time was exceeded and no response arrived","pos":"verb","example":"Requests began to time out after waiting more than 30 seconds for a free connection."}]},{"en":"**Detection and Response**\n\nThe on-call engineer received a PagerDuty alert at 14:09 UTC, two minutes after the service started failing. She checked the error logs and noticed the message 'connection pool exhausted.' She identified the recent config change as the likely fix point and reverted the deployment at 14:38 UTC. The service recovered fully within four minutes.","ru":"**Обнаружение и реакция**\n\nДежурный инженер получил оповещение из PagerDuty в 14:09 UTC — через две минуты после начала сбоя. Она проверила логи ошибок и заметила сообщение «connection pool exhausted» (пул соединений исчерпан). Она определила недавнее изменение конфига как вероятную точку восстановления и откатила деплой в 14:38 UTC. Сервис полностью восстановился в течение четырёх минут.","words":[{"id":"b1e-postmortem-w8","w":"on-call engineer","ru":"дежурный инженер","gloss":"an engineer who is responsible for responding to alerts and incidents outside normal working hours","pos":"phrase","example":"The on-call engineer must respond to a P1 alert within five minutes."},{"id":"b1e-postmortem-w9","w":"revert","ru":"откатить","gloss":"to undo a recent change and return the system to its previous working state","pos":"verb","ipa":"rɪˈvɜːt","example":"When the deploy caused errors, the team reverted to the last stable version."},{"id":"b1e-postmortem-w10","w":"exhausted","ru":"исчерпан","gloss":"fully used up — here, all connections in the pool were in use and none were available","pos":"adj","ipa":"ɪɡˈzɔːstɪd","example":"The thread pool was exhausted and new requests had to wait."}]},{"en":"**Lessons and Action Items**\n\nThis incident was blameless — the engineer who made the config change followed the standard process. The process itself had a gap: there was no automated check that validates connection pool settings before a deploy reaches production. The team agreed on three action items: (1) add a pre-deploy config validation step to the CI pipeline; (2) add a dashboard alert for connection pool usage above 80%; (3) document the minimum safe pool size in the runbook.","ru":"**Выводы и задачи**\n\nЭтот инцидент был рассмотрен без обвинений — инженер, внёсший изменение конфига, следовал стандартному процессу. В самом процессе была пробел: отсутствовала автоматическая проверка настроек пула соединений до попадания деплоя в продакшен. Команда согласовала три задачи: (1) добавить шаг валидации конфига перед деплоем в CI-пайплайн; (2) добавить оповещение на дашборде при использовании пула соединений выше 80%; (3) задокументировать минимально безопасный размер пула в runbook.","words":[{"id":"b1e-postmortem-w11","w":"blameless","ru":"без обвинений","gloss":"a postmortem style where the goal is to fix the process, not to punish the person who made a mistake","pos":"adj","ipa":"ˈbleɪmləs","example":"Blameless postmortems encourage engineers to report mistakes without fear."},{"id":"b1e-postmortem-w12","w":"action item","ru":"задача к выполнению","gloss":"a specific task with a clear owner that must be completed to prevent the same problem from happening again","pos":"phrase","example":"Each action item from the postmortem was assigned an owner and a due date."},{"id":"b1e-postmortem-w13","w":"runbook","ru":"руководство по устранению неполадок","gloss":"a document that describes step-by-step procedures for operating or fixing a system","pos":"noun","ipa":"ˈrʌnbʊk","example":"The runbook explains how to safely restart the database without data loss."}]}],"phrases":[{"id":"b1e-postmortem-p1","en":"run out of connections","ru":"исчерпать соединения","note":{"en":"Means all available connections in the pool were in use, so new requests had to wait or fail.","ru":"Означает, что все доступные соединения в пуле заняты и новые запросы вынуждены ждать или завершаться с ошибкой."}},{"id":"b1e-postmortem-p2","en":"revert the deployment","ru":"откатить деплой","note":{"en":"Roll back to the previous version of the code or config that was known to work.","ru":"Вернуться к предыдущей версии кода или конфига, которая работала стабильно."}},{"id":"b1e-postmortem-p3","en":"estimated revenue impact","ru":"предполагаемые потери выручки","note":{"en":"A calculated guess of how much money was lost due to the incident, based on average transaction value and volume.","ru":"Расчётная оценка потерь выручки из-за инцидента, основанная на средней стоимости и объёме транзакций."}}],"questions":[{"id":"b1e-postmortem-q1","q":{"en":"What was the root cause of the outage?","ru":"Какова была первопричина сбоя?"},"options":[{"en":"A bug in the payment processing code","ru":"Ошибка в коде обработки платежей"},{"en":"A database connection pool set to too small a value","ru":"Слишком маленькое значение пула соединений с базой данных"},{"en":"A network failure between servers","ru":"Сетевой сбой между серверами"}],"answer":1,"explain":{"en":"The config change set the connection pool size to 2 instead of 20, so the service quickly ran out of database connections under normal traffic.","ru":"Изменение конфига задало размер пула соединений равным 2 вместо 20, поэтому сервис быстро исчерпал соединения с базой данных при обычном трафике."}},{"id":"b1e-postmortem-q2","q":{"en":"How did the on-call engineer identify the problem?","ru":"Как дежурный инженер выявил проблему?"},"options":[{"en":"She received a customer complaint email","ru":"Она получила письмо с жалобой от клиента"},{"en":"She saw the error in a code review","ru":"Она увидела ошибку в ревью кода"},{"en":"She checked the error logs and found 'connection pool exhausted'","ru":"Она проверила логи ошибок и нашла сообщение «connection pool exhausted»"}],"answer":2,"explain":{"en":"The engineer read the error logs and saw the specific message 'connection pool exhausted', which pointed directly to the misconfigured pool size.","ru":"Инженер прочитала логи ошибок и увидела конкретное сообщение «connection pool exhausted», которое напрямую указывало на неверно настроенный размер пула."}},{"id":"b1e-postmortem-q3","q":{"en":"Why does the postmortem say the incident was 'blameless'?","ru":"Почему в постмортеме сказано, что инцидент был рассмотрен «без обвинений»?"},"options":[{"en":"Because no one was responsible for the change","ru":"Потому что никто не нёс ответственности за изменение"},{"en":"Because the engineer followed the standard process; the process itself had the gap","ru":"Потому что инженер следовал стандартному процессу, а пробел был именно в самом процессе"},{"en":"Because the impact was too small to matter","ru":"Потому что последствия были слишком незначительными"}],"answer":1,"explain":{"en":"Blameless means the focus is on fixing the process, not punishing people. The engineer did nothing wrong; the process lacked a config validation step.","ru":"«Без обвинений» означает, что цель — исправить процесс, а не наказывать людей. Инженер ничего не нарушил; в процессе просто не хватало шага валидации конфига."}},{"id":"b1e-postmortem-q4","q":{"en":"Which action item was agreed to detect this type of problem in the future?","ru":"Какая задача была согласована для обнаружения подобных проблем в будущем?"},"options":[{"en":"Hire more on-call engineers","ru":"Нанять больше дежурных инженеров"},{"en":"Add a pre-deploy config validation step to the CI pipeline","ru":"Добавить шаг валидации конфига перед деплоем в CI-пайплайн"},{"en":"Reduce the number of database connections allowed per request","ru":"Уменьшить количество допустимых соединений с базой данных на запрос"}],"answer":1,"explain":{"en":"The team decided to add an automated config validation check to the CI pipeline so that an incorrect pool size would be caught before reaching production.","ru":"Команда решила добавить автоматическую проверку конфига в CI-пайплайн, чтобы неверный размер пула выявлялся до попадания в продакшен."}}],"targetWords":["ngsl:1495","ngsl:0972","ngsl:1125","ngsl:0881"]},
  {"id":"b1e-api-docs","level":"B1","stream":"engineering","title":{"en":"API Reference: Create Order Endpoint","ru":"Справочник API: эндпоинт создания заказа"},"blurb":{"en":"An excerpt from API documentation describing how to create an order, what the server returns on success, and how to handle common errors.","ru":"Фрагмент документации к API: как создать заказ, что возвращает сервер при успехе и как обрабатывать распространённые ошибки."},"source":{"en":"API reference documentation","ru":"Справочная документация API"},"passages":[{"en":"**POST /v1/orders**\n\nCreates a new order for the authenticated user. This endpoint requires a valid API key passed in the `Authorization` header. The request body must be a JSON object. All fields marked as required must be present; if any required field is missing, the server returns a `400 Bad Request` error.","ru":"**POST /v1/orders**\n\nСоздаёт новый заказ для аутентифицированного пользователя. Для этого эндпоинта требуется действующий API-ключ, передаваемый в заголовке `Authorization`. Тело запроса должно быть объектом JSON. Все поля, помеченные как обязательные, должны присутствовать; если обязательное поле отсутствует, сервер возвращает ошибку `400 Bad Request`.","words":[{"id":"b1e-api-docs-w1","w":"endpoint","ru":"эндпоинт","gloss":"a specific URL in an API that accepts a request and performs one action, such as creating or retrieving a resource","pos":"noun","ipa":"ˈendpɔɪnt","example":"The /v1/orders endpoint handles all order creation requests."},{"id":"b1e-api-docs-w2","w":"authenticated","ru":"аутентифицированный","gloss":"proved to be who they say they are — here, a user who has provided a valid API key","pos":"adj","ipa":"ɔːˈθentɪkeɪtɪd","example":"Only authenticated requests are allowed to access the orders endpoint."},{"id":"b1e-api-docs-w3","w":"request body","ru":"тело запроса","gloss":"the data sent along with an HTTP request, usually as JSON, containing the information the server needs to process the action","pos":"phrase","example":"The request body must include the item IDs and the delivery address."},{"id":"b1e-api-docs-w4","w":"400 Bad Request","ru":"400 Bad Request (неверный запрос)","gloss":"an HTTP error code meaning the client sent something the server could not understand or accept — often a missing or invalid field","pos":"phrase","example":"The server returned 400 Bad Request because the email field was empty."}]},{"en":"**Request Parameters**\n\n| Field | Type | Required | Description |\n|---|---|---|---|\n| `items` | array | yes | A list of item objects. Each item must include `product_id` (string) and `quantity` (integer, min 1). |\n| `shipping_address` | object | yes | The delivery address. Must include `street`, `city`, and `country`. |\n| `coupon_code` | string | no | An optional discount code. If the code is invalid, the order is still created but no discount is applied. |","ru":"**Параметры запроса**\n\n| Поле | Тип | Обязательное | Описание |\n|---|---|---|---|\n| `items` | массив | да | Список объектов товаров. Каждый товар должен содержать `product_id` (строка) и `quantity` (целое число, мин. 1). |\n| `shipping_address` | объект | да | Адрес доставки. Должен включать `street`, `city` и `country`. |\n| `coupon_code` | строка | нет | Необязательный код скидки. Если код недействителен, заказ всё равно создаётся, но скидка не применяется. |","words":[{"id":"b1e-api-docs-w5","w":"array","ru":"массив","gloss":"an ordered list of values, written in JSON as [ item1, item2, item3 ]","pos":"noun","ipa":"əˈreɪ","example":"The items field is an array, so you can include multiple products in one order."},{"id":"b1e-api-docs-w6","w":"integer","ru":"целое число","gloss":"a whole number with no decimal point, such as 1, 5, or 100","pos":"noun","ipa":"ˈɪntɪdʒər","example":"The quantity field must be an integer — you cannot order 1.5 items."},{"id":"b1e-api-docs-w7","w":"optional","ru":"необязательный","gloss":"not required — you may include it if you want, but the request will succeed without it","pos":"adj","ipa":"ˈɒpʃənəl","example":"The coupon_code field is optional; most requests will not include it."}]},{"en":"**Success Response — 201 Created**\n\nIf the request is valid, the server returns HTTP status `201 Created` with a JSON body. The response includes the new order's `id`, its `status` (always `\"pending\"` at creation), the `total_amount` in cents, and a `created_at` timestamp in ISO 8601 format. The `id` should be stored by the client and used in future requests to check or update the order.","ru":"**Успешный ответ — 201 Created**\n\nЕсли запрос корректен, сервер возвращает HTTP-статус `201 Created` с телом JSON. Ответ содержит `id` нового заказа, его `status` (всегда `\"pending\"` при создании), `total_amount` в центах и метку времени `created_at` в формате ISO 8601. `id` следует сохранить на стороне клиента и использовать в последующих запросах для проверки или обновления заказа.","words":[{"id":"b1e-api-docs-w8","w":"201 Created","ru":"201 Created (создано)","gloss":"an HTTP status code meaning the request succeeded and a new resource was created on the server","pos":"phrase","example":"A successful POST to /v1/orders returns 201 Created with the order details."},{"id":"b1e-api-docs-w9","w":"timestamp","ru":"метка времени","gloss":"a value that records the exact date and time when something happened","pos":"noun","ipa":"ˈtaɪmstæmp","example":"The created_at timestamp tells you exactly when the order was placed."},{"id":"b1e-api-docs-w10","w":"ISO 8601","ru":"ISO 8601","gloss":"an international standard format for dates and times, e.g. 2026-05-14T14:07:00Z","pos":"phrase","example":"All timestamps in the API use ISO 8601 format so clients in any timezone can parse them correctly."}]},{"en":"**Error Responses**\n\n| Status | Code | Meaning |\n|---|---|---|\n| 400 | `MISSING_FIELD` | A required field is absent from the request body. |\n| 400 | `INVALID_QUANTITY` | A quantity value is less than 1 or is not an integer. |\n| 401 | `UNAUTHORIZED` | The `Authorization` header is missing or the API key is invalid. |\n| 422 | `PRODUCT_NOT_FOUND` | One or more `product_id` values do not exist in the catalog. |\n| 500 | `INTERNAL_ERROR` | An unexpected server error occurred. Retry after a short delay. |\n\nAll error responses use the same JSON shape: `{ \"code\": \"...\", \"message\": \"...\" }`. The `message` field contains a human-readable description of the problem.","ru":"**Ответы с ошибками**\n\n| Статус | Код | Смысл |\n|---|---|---|\n| 400 | `MISSING_FIELD` | Обязательное поле отсутствует в теле запроса. |\n| 400 | `INVALID_QUANTITY` | Значение количества меньше 1 или не является целым числом. |\n| 401 | `UNAUTHORIZED` | Заголовок `Authorization` отсутствует или API-ключ недействителен. |\n| 422 | `PRODUCT_NOT_FOUND` | Один или несколько `product_id` не существуют в каталоге. |\n| 500 | `INTERNAL_ERROR` | Произошла непредвиденная ошибка сервера. Повторите попытку через небольшой промежуток времени. |\n\nВсе ответы с ошибками используют одну и ту же структуру JSON: `{ \"code\": \"...\", \"message\": \"...\" }`. Поле `message` содержит описание проблемы, понятное человеку.","words":[{"id":"b1e-api-docs-w11","w":"401 Unauthorized","ru":"401 Unauthorized (не авторизован)","gloss":"an HTTP error meaning the request did not include valid credentials — the server refuses to process it until the client identifies itself correctly","pos":"phrase","example":"If you forget to include the API key, you will receive 401 Unauthorized."},{"id":"b1e-api-docs-w12","w":"human-readable","ru":"понятный человеку","gloss":"written in plain language so a developer or user can understand it directly, rather than being a raw code or number","pos":"adj","example":"The error message is human-readable, so you can show it directly in a support ticket."},{"id":"b1e-api-docs-w13","w":"retry","ru":"повторная попытка","gloss":"to send the same request again after a failure, usually after waiting a short time","pos":"verb","ipa":"ˌriːˈtraɪ","example":"On a 500 error, wait two seconds and then retry the request once."}]},{"en":"**Code Example — cURL**\n\n```\ncurl -X POST https://api.example.com/v1/orders \\\n  -H \"Authorization: Bearer sk_live_abc123\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"items\":[{\"product_id\":\"prod_9\",\"quantity\":2}],\"shipping_address\":{\"street\":\"12 Oak St\",\"city\":\"Berlin\",\"country\":\"DE\"}}'\n```\n\nThis request creates an order for two units of product `prod_9` and ships it to Berlin. If successful, the response body will contain the new order ID.","ru":"**Пример кода — cURL**\n\n```\ncurl -X POST https://api.example.com/v1/orders \\\n  -H \"Authorization: Bearer sk_live_abc123\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"items\":[{\"product_id\":\"prod_9\",\"quantity\":2}],\"shipping_address\":{\"street\":\"12 Oak St\",\"city\":\"Berlin\",\"country\":\"DE\"}}'\n```\n\nЭтот запрос создаёт заказ на два экземпляра продукта `prod_9` с доставкой в Берлин. В случае успеха тело ответа будет содержать идентификатор нового заказа.","words":[{"id":"b1e-api-docs-w14","w":"Bearer token","ru":"Bearer-токен","gloss":"a type of API key sent in the Authorization header with the word 'Bearer' before it — the server accepts any request that includes a valid token","pos":"phrase","example":"Pass your API key as a Bearer token: Authorization: Bearer sk_live_abc123."},{"id":"b1e-api-docs-w15","w":"Content-Type","ru":"Content-Type (тип содержимого)","gloss":"an HTTP header that tells the server what format the request body is in — 'application/json' means it is a JSON object","pos":"phrase","example":"Set Content-Type: application/json so the server knows how to parse your request body."}]}],"phrases":[{"id":"b1e-api-docs-p1","en":"returns a 400 Bad Request","ru":"возвращает 400 Bad Request","note":{"en":"The server sends back HTTP status 400, meaning it could not process the request because of a client-side problem such as a missing field.","ru":"Сервер отправляет HTTP-статус 400, означающий, что он не смог обработать запрос из-за проблемы на стороне клиента, например отсутствующего поля."}},{"id":"b1e-api-docs-p2","en":"store the id for future requests","ru":"сохранить id для последующих запросов","note":{"en":"Save the order ID returned by the server so you can reference the order in later API calls, for example to check its status or cancel it.","ru":"Сохраните идентификатор заказа, возвращённый сервером, чтобы ссылаться на него в последующих вызовах API — например, для проверки статуса или отмены."}},{"id":"b1e-api-docs-p3","en":"retry after a short delay","ru":"повторить попытку через небольшой промежуток времени","note":{"en":"Wait a few seconds before sending the same request again — useful when the server returns a 500 error due to a temporary problem.","ru":"Подождите несколько секунд перед повторной отправкой того же запроса — полезно, когда сервер возвращает ошибку 500 из-за временной проблемы."}}],"questions":[{"id":"b1e-api-docs-q1","q":{"en":"Which HTTP method and path do you use to create a new order?","ru":"Какой HTTP-метод и путь используются для создания нового заказа?"},"options":[{"en":"GET /v1/orders","ru":"GET /v1/orders"},{"en":"POST /v1/orders","ru":"POST /v1/orders"},{"en":"PUT /v1/orders","ru":"PUT /v1/orders"}],"answer":1,"explain":{"en":"The documentation specifies POST /v1/orders for creating a new order. GET is used for reading data and PUT for updating an existing resource.","ru":"В документации указано POST /v1/orders для создания нового заказа. GET используется для чтения данных, PUT — для обновления существующего ресурса."}},{"id":"b1e-api-docs-q2","q":{"en":"What does the server return if the API key is missing from the request?","ru":"Что возвращает сервер, если API-ключ отсутствует в запросе?"},"options":[{"en":"400 MISSING_FIELD","ru":"400 MISSING_FIELD"},{"en":"422 PRODUCT_NOT_FOUND","ru":"422 PRODUCT_NOT_FOUND"},{"en":"401 UNAUTHORIZED","ru":"401 UNAUTHORIZED"}],"answer":2,"explain":{"en":"The error table shows that a missing or invalid Authorization header results in 401 UNAUTHORIZED, not a 400 error.","ru":"В таблице ошибок указано, что отсутствующий или недействительный заголовок Authorization приводит к ошибке 401 UNAUTHORIZED, а не 400."}},{"id":"b1e-api-docs-q3","q":{"en":"What happens if you include an invalid coupon_code in the request?","ru":"Что происходит, если в запросе указан недействительный код купона?"},"options":[{"en":"The server rejects the request with a 400 error","ru":"Сервер отклоняет запрос с ошибкой 400"},{"en":"The order is created but no discount is applied","ru":"Заказ создаётся, но скидка не применяется"},{"en":"The order is created with a default 10% discount","ru":"Заказ создаётся со скидкой 10% по умолчанию"}],"answer":1,"explain":{"en":"The parameters table states: 'If the code is invalid, the order is still created but no discount is applied.' The request does not fail.","ru":"В таблице параметров указано: «Если код недействителен, заказ всё равно создаётся, но скидка не применяется». Запрос не завершается ошибкой."}},{"id":"b1e-api-docs-q4","q":{"en":"What HTTP status code does the server return on a successful order creation?","ru":"Какой HTTP-статус возвращает сервер при успешном создании заказа?"},"options":[{"en":"200 OK","ru":"200 OK"},{"en":"201 Created","ru":"201 Created"},{"en":"204 No Content","ru":"204 No Content"}],"answer":1,"explain":{"en":"The success response section says the server returns 201 Created — the standard HTTP code for a newly created resource, distinct from 200 OK which is used for successful reads.","ru":"В разделе об успешном ответе указано, что сервер возвращает 201 Created — стандартный HTTP-код для вновь созданного ресурса, в отличие от 200 OK, который используется для успешного чтения."}}],"targetWords":["ngsl:1009","ngsl:1495","ngsl:1125","ngsl:0802","ngsl:0881"]},
  {"id":"b1e-blog-intro","level":"B1","stream":"engineering","title":{"en":"Why I Stopped Writing Long Functions","ru":"Почему я перестал писать длинные функции"},"blurb":{"en":"The opening of a developer blog post about the hidden costs of long functions and what the author learned after a painful production incident.","ru":"Вступление к посту в блоге разработчика о скрытых издержках длинных функций и о том, что автор понял после болезненного инцидента на продакшене."},"source":{"en":"Developer blog post (intro section)","ru":"Пост в блоге разработчика (вступительная часть)"},"passages":[{"en":"Last year our team pushed a small change to the billing service. The diff was only forty lines, but it broke invoicing for three hours. When we looked at the stack trace, the root cause was inside a function that was over four hundred lines long. Nobody on the team fully understood what it did. We fixed the immediate bug, but that afternoon I started thinking about why the function had grown so large in the first place.","ru":"В прошлом году наша команда внесла небольшое изменение в сервис биллинга. Diff составлял всего сорок строк, но он сломал выставление счетов на три часа. Когда мы изучили стек вызовов, корневая причина оказалась внутри функции длиной более четырёхсот строк. Никто в команде не понимал её полностью. Мы исправили непосредственную ошибку, но в тот день после полудня я начал думать о том, почему функция вообще разрослась до таких размеров.","words":[{"id":"b1e-blog-intro-w1","w":"billing service","ru":"сервис биллинга","gloss":"a part of the system that handles charging customers and generating invoices","pos":"phrase","example":"The billing service runs every night to generate monthly invoices."},{"id":"b1e-blog-intro-w2","w":"diff","ru":"дифф (разница в коде)","gloss":"a comparison showing which lines were added or removed between two versions of a file","pos":"noun","ipa":"dɪf","example":"Review the diff carefully before approving the pull request."},{"id":"b1e-blog-intro-w3","w":"stack trace","ru":"трассировка стека","gloss":"a report showing the sequence of function calls that led to an error","pos":"phrase","example":"The stack trace showed that the crash started in the database layer."},{"id":"b1e-blog-intro-w4","w":"root cause","ru":"первопричина","gloss":"the original, underlying reason a problem occurred, not just a symptom","pos":"phrase","example":"We use five-whys analysis to identify the root cause of every incident."}]},{"en":"The answer was simple: the function had grown by accumulation. Every time someone needed to add a feature, they added it at the bottom of the existing code. Nobody wanted to reorganize it because touching it felt risky — it was hard to identify all the ways the function was used. Over time, a small helper had become a place where unrelated logic lived together. This is a pattern I now call the 'junk drawer' anti-pattern.","ru":"Ответ был прост: функция разрасталась постепенно. Каждый раз, когда кому-то нужно было добавить функциональность, он добавлял её в конец существующего кода. Никто не хотел реорганизовывать функцию, потому что прикасаться к ней было рискованно — трудно было определить все способы её использования. Со временем небольшая вспомогательная функция превратилась в место, где жила несвязанная логика. Это паттерн, который я теперь называю антипаттерном «ящик с хламом».","words":[{"id":"b1e-blog-intro-w5","w":"accumulation","ru":"накопление","gloss":"the process of gradually growing larger by adding more things over time","pos":"noun","ipa":"əˌkjuːmjʊˈleɪʃən","example":"Technical debt grows through the accumulation of small shortcuts."},{"id":"b1e-blog-intro-w6","w":"identify","ru":"определять; идентифицировать","gloss":"to recognize or find out what something is or where it is used","pos":"verb","ipa":"aɪˈdentɪfaɪ","example":"It was hard to identify all the callers of this function."},{"id":"b1e-blog-intro-w7","w":"anti-pattern","ru":"антипаттерн","gloss":"a common solution that seems helpful at first but actually makes things worse","pos":"noun","example":"God objects and magic numbers are classic anti-patterns."}]},{"en":"Generally, a function should do one thing. This is not a new idea — it appears in every book about clean code. But the rule is easy to forget under deadline pressure. When a task is urgent, it is tempting to add a few lines to an existing function instead of creating a new one. The trouble is that 'a few lines' happens many times, and the function grows without anyone making a conscious decision to make it large.","ru":"В целом функция должна делать одно дело. Это не новая идея — она встречается в каждой книге о чистом коде. Но правило легко забыть под давлением дедлайна. Когда задача срочная, соблазнительно добавить несколько строк в существующую функцию вместо создания новой. Проблема в том, что «несколько строк» добавляется много раз, и функция разрастается без того, чтобы кто-то сознательно принял решение сделать её большой.","words":[{"id":"b1e-blog-intro-w8","w":"generally","ru":"в целом; обычно","gloss":"in most cases; as a usual rule","pos":"adv","ipa":"ˈdʒenərəli","example":"Stateless services are generally easier to scale."},{"id":"b1e-blog-intro-w9","w":"clean code","ru":"чистый код","gloss":"code that is easy to read, understand, and maintain because it is well-structured","pos":"phrase","example":"Clean code uses descriptive names and short, focused functions."},{"id":"b1e-blog-intro-w10","w":"trouble","ru":"проблема; затруднение","gloss":"a difficulty or situation that causes problems","pos":"noun","ipa":"ˈtrʌbəl","example":"The deployment ran into trouble because of a missing config value."}]},{"en":"After the incident, I refactored the billing function into seven smaller functions. Each one had a clear name and a single responsibility. The refactor took two days — much longer than I wanted. But the next pull request that touched that area was reviewed and merged in thirty minutes. My investment of two days saved the team hours of confusion every month. That convinced me: keeping functions short is not about style, it is about the speed at which a team can safely change code.","ru":"После инцидента я разбил функцию биллинга на семь меньших функций. Каждая из них имела понятное название и единственную ответственность. Рефакторинг занял два дня — намного дольше, чем я хотел. Но следующий пул-реквест, затрагивавший этот код, был проверен и принят за тридцать минут. Мои инвестиции в два дня сэкономили команде часы путаницы каждый месяц. Это убедило меня: короткие функции — это не вопрос стиля, а вопрос скорости, с которой команда может безопасно изменять код.","words":[{"id":"b1e-blog-intro-w11","w":"refactor","ru":"рефакторинг; проводить рефакторинг","gloss":"to restructure existing code without changing what it does, to make it cleaner or easier to maintain","pos":"verb","example":"We refactored the payment module to remove duplicated logic."},{"id":"b1e-blog-intro-w12","w":"single responsibility","ru":"единственная ответственность","gloss":"the principle that a function or class should have only one reason to change","pos":"phrase","example":"The single responsibility principle helps keep modules independent."},{"id":"b1e-blog-intro-w13","w":"investment","ru":"инвестиция; вложение","gloss":"time or effort spent now in order to gain a benefit later","pos":"noun","ipa":"ɪnˈvestmənt","example":"Good test coverage is an investment that pays off over time."}]},{"en":"In the rest of this post I will share three practical rules I now follow when writing functions. They are not difficult to apply, and you do not need any special tools. The only thing you need is the habit of asking one question before you add new code to an existing function: 'Does this belong here, or does it deserve its own name?'","ru":"В остальной части поста я поделюсь тремя практическими правилами, которым теперь следую при написании функций. Их несложно применять, и вам не нужны какие-либо специальные инструменты. Единственное, что вам нужно, — это привычка задавать один вопрос перед добавлением нового кода в существующую функцию: «Это сюда относится или заслуживает собственного имени?»","words":[{"id":"b1e-blog-intro-w14","w":"habit","ru":"привычка","gloss":"something you do regularly, often without thinking about it","pos":"noun","ipa":"ˈhæbɪt","example":"Writing tests first is a good habit for catching bugs early."}]}],"phrases":[{"id":"b1e-blog-intro-p1","en":"root cause","ru":"первопричина","note":{"en":"Used in engineering post-mortems to describe the deepest reason a failure happened, not a surface symptom.","ru":"Используется в разборах инцидентов для описания глубинной причины сбоя, а не поверхностного симптома."}},{"id":"b1e-blog-intro-p2","en":"under deadline pressure","ru":"под давлением дедлайна","note":{"en":"Describes the stressful situation when a feature must be finished by a fixed date, which often leads to shortcuts.","ru":"Описывает стрессовую ситуацию, когда функция должна быть готова к фиксированной дате, что часто приводит к компромиссам."}},{"id":"b1e-blog-intro-p3","en":"pays off","ru":"окупается","note":{"en":"Means that an earlier effort or investment eventually produces a good result or saves resources.","ru":"Означает, что ранее вложенные усилия или ресурсы в итоге дают хороший результат или экономию."}}],"questions":[{"id":"b1e-blog-intro-q1","q":{"en":"Why did nobody want to reorganize the four-hundred-line function before the incident?","ru":"Почему никто не хотел реорганизовывать функцию на четыреста строк до инцидента?"},"options":[{"en":"It was hard to identify all the places where the function was used, so touching it felt risky.","ru":"Было сложно определить все места использования функции, поэтому трогать её казалось рискованным."},{"en":"The team did not have enough time in their sprint to do a refactor.","ru":"У команды не было достаточно времени в спринте для проведения рефакторинга."},{"en":"The function was protected by a rule that prevented any changes to it.","ru":"Функция была защищена правилом, запрещавшим вносить в неё изменения."}],"answer":0,"explain":{"en":"The text says 'touching it felt risky — it was hard to identify all the ways the function was used', which matches option A.","ru":"В тексте говорится: «прикасаться к ней было рискованно — трудно было определить все способы её использования», что соответствует варианту А."}},{"id":"b1e-blog-intro-q2","q":{"en":"According to the author, what is the 'junk drawer' anti-pattern?","ru":"По словам автора, что такое антипаттерн «ящик с хламом»?"},"options":[{"en":"A function that is called from too many different places in the codebase.","ru":"Функция, которая вызывается из слишком многих мест в кодовой базе."},{"en":"A function that grows large because unrelated logic is added to it over time.","ru":"Функция, которая разрастается, потому что со временем в неё добавляется несвязанная логика."},{"en":"A function that was written quickly under deadline pressure and never tested.","ru":"Функция, написанная быстро под давлением дедлайна и никогда не протестированная."}],"answer":1,"explain":{"en":"The author describes it as 'a place where unrelated logic lived together', which is option B.","ru":"Автор описывает его как «место, где жила несвязанная логика», что соответствует варианту Б."}},{"id":"b1e-blog-intro-q3","q":{"en":"What practical benefit did the author see after the two-day refactor?","ru":"Какую практическую пользу автор увидел после двухдневного рефакторинга?"},"options":[{"en":"The billing service stopped having any incidents for the rest of the year.","ru":"Сервис биллинга перестал иметь какие-либо инциденты до конца года."},{"en":"The next pull request touching that code was reviewed and merged in thirty minutes.","ru":"Следующий пул-реквест, затрагивавший этот код, был проверен и принят за тридцать минут."},{"en":"The team was able to add three new features to the billing service that week.","ru":"Команда смогла добавить три новые функции в сервис биллинга на той же неделе."}],"answer":1,"explain":{"en":"The author states: 'the next pull request that touched that area was reviewed and merged in thirty minutes', matching option B.","ru":"Автор говорит: «следующий пул-реквест, затрагивавший этот код, был проверен и принят за тридцать минут», что соответствует варианту Б."}},{"id":"b1e-blog-intro-q4","q":{"en":"What question does the author recommend asking before adding code to an existing function?","ru":"Какой вопрос автор рекомендует задавать перед добавлением кода в существующую функцию?"},"options":[{"en":"'How long will this function be after I add the new code?'","ru":"«Какой длины будет эта функция после добавления нового кода?»"},{"en":"'Does this belong here, or does it deserve its own name?'","ru":"«Это сюда относится или заслуживает собственного имени?»"},{"en":"'Will my reviewer approve this change without asking questions?'","ru":"«Одобрит ли мой ревьюер это изменение без вопросов?»"}],"answer":1,"explain":{"en":"The author explicitly states this question in the final paragraph.","ru":"Автор прямо формулирует этот вопрос в последнем абзаце."}}],"targetWords":["ngsl:0805","ngsl:0821","ngsl:0831","ngsl:0841","ngsl:0847"]},
  {"id":"b1e-review-disagreement","level":"B1","stream":"engineering","title":{"en":"Code Review: Should We Add a Retry Layer?","ru":"Ревью кода: нужен ли нам слой повторных попыток?"},"blurb":{"en":"Two engineers respectfully disagree about adding automatic retries to an HTTP client. They weigh reliability gains against hidden risks.","ru":"Два инженера вежливо расходятся во мнениях о добавлении автоматических повторных попыток в HTTP-клиент. Они взвешивают улучшение надёжности и скрытые риски."},"source":{"en":"Pull-request review thread","ru":"Обсуждение в пул-реквесте"},"passages":[{"en":"**PR #891 — Add automatic retry logic to PaymentClient**\n\n**Reviewer (Sara):** I appreciate the motivation here — transient network errors are a real problem, and a retry layer would improve reliability. That said, I have a concern. The current implementation retries all failed requests, including POST requests to the payment API. Retrying a POST that already succeeded on the server but returned a network error to the client could charge the customer twice. This is a potential issue we need to think about carefully.","ru":"**PR #891 — Добавить логику автоматических повторных попыток в PaymentClient**\n\n**Ревьюер (Сара):** Я ценю мотивацию — транзиентные сетевые ошибки — реальная проблема, и слой повторных попыток улучшил бы надёжность. Тем не менее у меня есть опасение. Текущая реализация повторяет все неудавшиеся запросы, включая POST-запросы к API платежей. Повторная попытка POST, который уже выполнился на сервере, но вернул сетевую ошибку клиенту, могла бы дважды снять деньги с клиента. Это потенциальная проблема, которую нам нужно тщательно обдумать.","words":[{"id":"b1e-review-disagreement-w1","w":"transient","ru":"временный; транзиентный","gloss":"lasting only for a short time; a transient error disappears on its own without a code fix","pos":"adj","ipa":"ˈtrænziənt","example":"A transient network error often resolves if you simply retry the request."},{"id":"b1e-review-disagreement-w2","w":"retry","ru":"повторная попытка; повторять запрос","gloss":"to try a failed operation again, hoping it will succeed the second time","pos":"verb","ipa":"ˌriːˈtraɪ","example":"The client will retry up to three times with exponential backoff."},{"id":"b1e-review-disagreement-w3","w":"potential","ru":"потенциальный; возможный","gloss":"possible but not yet certain; something that might become a real problem","pos":"adj","ipa":"pəˈtenʃəl","example":"We identified a potential security vulnerability in the auth flow."},{"id":"b1e-review-disagreement-w4","w":"idempotent","ru":"идемпотентный","gloss":"an operation that produces the same result whether you call it once or many times","pos":"adj","ipa":"aɪˈdempətənt","example":"GET and PUT are idempotent; POST is generally not."}]},{"en":"**Author (Marco):** That is a fair point. My intention was to avoid the situation where a single dropped packet causes the whole payment to fail. I agree that blindly retrying POST requests is not safe. However, I think we can solve this by only retrying on specific HTTP status codes — for example, 429 (rate limited) and 503 (service unavailable). Both of those indicate that the server never processed the request, so a retry is safe. What do you think of that approach?","ru":"**Автор (Марко):** Это справедливое замечание. Моё намерение состояло в том, чтобы избежать ситуации, когда один потерявшийся пакет приводит к сбою всего платежа. Я согласен, что слепо повторять POST-запросы небезопасно. Однако я думаю, что мы можем решить это, повторяя попытки только при определённых HTTP-статусах — например, 429 (слишком много запросов) и 503 (сервис недоступен). Оба они указывают, что сервер никогда не обрабатывал запрос, поэтому повторная попытка безопасна. Что ты думаешь о таком подходе?","words":[{"id":"b1e-review-disagreement-w5","w":"avoid","ru":"избегать","gloss":"to keep away from something; to prevent something from happening","pos":"verb","ipa":"əˈvɔɪd","example":"Avoid using SELECT * in production queries for performance reasons."},{"id":"b1e-review-disagreement-w6","w":"indicate","ru":"указывать; свидетельствовать","gloss":"to show or signal that something is true or has happened","pos":"verb","ipa":"ˈɪndɪkeɪt","example":"A 503 status code indicates the server is temporarily unavailable."},{"id":"b1e-review-disagreement-w7","w":"status code","ru":"код статуса","gloss":"a three-digit number returned by an HTTP server to describe the result of a request","pos":"phrase","example":"A 200 status code means the request succeeded."}]},{"en":"**Sara:** Retrying on 429 and 503 is a much safer strategy. I still want to mention one more thing: we should add a maximum retry count and an exponential backoff delay. Without these, if the payment service suffers a long outage, our client could send thousands of requests per second and make the recovery harder. Generally, a good retry implementation does not just try again — it tries again more slowly each time.","ru":"**Сара:** Повторять попытки при 429 и 503 — гораздо более безопасная стратегия. Я всё же хочу упомянуть ещё одну вещь: нам следует добавить максимальное количество повторных попыток и задержку с экспоненциальным отступом. Без них, если сервис платежей переживёт длительный сбой, наш клиент может отправлять тысячи запросов в секунду и затруднять восстановление. В целом хорошая реализация повторных попыток не просто пробует снова — она пробует снова всё медленнее с каждым разом.","words":[{"id":"b1e-review-disagreement-w8","w":"strategy","ru":"стратегия","gloss":"a plan for how to handle a situation in a consistent way","pos":"noun","ipa":"ˈstrætədʒi","example":"A good retry strategy includes exponential backoff with jitter."},{"id":"b1e-review-disagreement-w9","w":"suffer","ru":"переживать; страдать","gloss":"to experience something bad, such as an outage or performance problem","pos":"verb","ipa":"ˈsʌfə","example":"Performance can suffer if you make synchronous calls in a hot path."},{"id":"b1e-review-disagreement-w10","w":"exponential backoff","ru":"экспоненциальный отступ","gloss":"a retry strategy where the wait time doubles (or grows fast) after each failed attempt, to avoid overwhelming a struggling server","pos":"phrase","example":"With exponential backoff, retries happen after 1 s, 2 s, 4 s, 8 s."},{"id":"b1e-review-disagreement-w11","w":"generally","ru":"в целом; обычно","gloss":"in most cases; as a usual rule","pos":"adv","ipa":"ˈdʒenərəli","example":"Stateless services are generally easier to scale horizontally."}]},{"en":"**Marco:** Completely agree on both points. I will update the implementation to add a maximum of three retries and a starting delay of 500 milliseconds that doubles on each attempt. I will also add a comment in the code to explain why we only retry on those two status codes, so the next engineer who reads this file understands the reasoning. Thanks for the careful review — this is exactly the kind of feedback that makes the codebase more reliable.","ru":"**Марко:** Полностью согласен по обоим пунктам. Я обновлю реализацию, добавив максимум три повторных попытки и начальную задержку в 500 миллисекунд, удваивающуюся при каждой попытке. Я также добавлю комментарий в коде, объясняющий, почему мы повторяем попытки только при этих двух кодах статуса, чтобы следующий инженер, читающий этот файл, понял логику. Спасибо за внимательное ревью — именно такая обратная связь делает кодовую базу более надёжной.","words":[{"id":"b1e-review-disagreement-w12","w":"file","ru":"файл","gloss":"a named collection of data stored on a computer, such as a source code file","pos":"noun","ipa":"faɪl","example":"The configuration file controls the server's startup behavior."},{"id":"b1e-review-disagreement-w13","w":"reasoning","ru":"обоснование; логика","gloss":"the thinking or logic behind a decision","pos":"noun","example":"A good commit message explains the reasoning, not just the change."}]}],"phrases":[{"id":"b1e-review-disagreement-p1","en":"that said","ru":"тем не менее; однако","note":{"en":"Used to introduce a concern or contrasting point after agreeing with something. Very common in polite code-review comments.","ru":"Используется для введения оговорки или контрастирующей точки зрения после согласия с чем-либо. Очень распространено в вежливых комментариях к ревью кода."}},{"id":"b1e-review-disagreement-p2","en":"fair point","ru":"справедливое замечание","note":{"en":"A polite way to acknowledge that the other person has made a valid argument, even if you want to refine or push back on it.","ru":"Вежливый способ признать, что другой человек привёл весомый аргумент, даже если вы хотите его уточнить или возразить."}},{"id":"b1e-review-disagreement-p3","en":"make the recovery harder","ru":"затруднять восстановление","note":{"en":"Describes the risk of 'retry storms' — where many clients sending rapid retries stop a failing service from recovering.","ru":"Описывает риск «шторма повторных попыток» — когда множество клиентов, отправляющих частые запросы, мешают восстановлению сбоящего сервиса."}}],"questions":[{"id":"b1e-review-disagreement-q1","q":{"en":"What specific danger does Sara identify with retrying all failed POST requests?","ru":"Какую конкретную опасность Сара видит в повторе всех неудачных POST-запросов?"},"options":[{"en":"The server could reject the retry because it has a duplicate-request filter.","ru":"Сервер может отклонить повторный запрос, так как у него есть фильтр дублирующихся запросов."},{"en":"The customer could be charged twice if the first request already succeeded on the server.","ru":"С клиента могут дважды снять деньги, если первый запрос уже выполнился на сервере."},{"en":"The retry could fail again and cause an infinite loop in the client code.","ru":"Повторная попытка может снова завершиться неудачей и привести к бесконечному циклу в клиентском коде."}],"answer":1,"explain":{"en":"Sara says retrying a POST that already succeeded on the server 'could charge the customer twice', which is option B.","ru":"Сара говорит, что повтор POST, который уже выполнился на сервере, «мог бы дважды снять деньги с клиента», что соответствует варианту Б."}},{"id":"b1e-review-disagreement-q2","q":{"en":"On which HTTP status codes does Marco propose to limit retries, and why are they safe?","ru":"При каких HTTP-статусах Марко предлагает ограничить повторные попытки и почему они безопасны?"},"options":[{"en":"429 and 503, because both indicate the server never processed the request.","ru":"429 и 503, потому что оба указывают, что сервер никогда не обрабатывал запрос."},{"en":"500 and 502, because both indicate a server-side crash that has already been fixed.","ru":"500 и 502, потому что оба указывают на серверный сбой, который уже был исправлен."},{"en":"408 and 504, because both indicate a timeout that means the request is lost.","ru":"408 и 504, потому что оба указывают на таймаут, означающий потерю запроса."}],"answer":0,"explain":{"en":"Marco says 429 and 503 'indicate that the server never processed the request, so a retry is safe'. This is option A.","ru":"Марко говорит, что 429 и 503 «указывают, что сервер никогда не обрабатывал запрос, поэтому повторная попытка безопасна». Это вариант А."}},{"id":"b1e-review-disagreement-q3","q":{"en":"Why does Sara say that retrying without a delay could make a recovery harder?","ru":"Почему Сара говорит, что повторные попытки без задержки могут затруднить восстановление?"},"options":[{"en":"Because the client would give up too quickly and show the user an error message.","ru":"Потому что клиент слишком быстро сдастся и покажет пользователю сообщение об ошибке."},{"en":"Because the logs would fill up with error messages and hide the real problem.","ru":"Потому что журналы заполнятся сообщениями об ошибках и скроют реальную проблему."},{"en":"Because the client could send thousands of requests per second during an outage, overwhelming the recovering server.","ru":"Потому что клиент может отправлять тысячи запросов в секунду во время сбоя, перегружая восстанавливающийся сервер."}],"answer":2,"explain":{"en":"Sara warns that without a delay 'our client could send thousands of requests per second and make the recovery harder', which is option C.","ru":"Сара предупреждает, что без задержки «наш клиент может отправлять тысячи запросов в секунду и затруднять восстановление», что соответствует варианту В."}},{"id":"b1e-review-disagreement-q4","q":{"en":"What does Marco plan to add to the code beyond the retry logic itself?","ru":"Что Марко планирует добавить в код помимо самой логики повторных попыток?"},"options":[{"en":"A unit test that verifies the retry count and the backoff delays.","ru":"Модульный тест, проверяющий количество повторных попыток и задержки отступа."},{"en":"A comment explaining why retries are limited to those two status codes.","ru":"Комментарий, объясняющий, почему повторные попытки ограничены этими двумя кодами статуса."},{"en":"A configuration file so the retry count can be changed without redeploying.","ru":"Файл конфигурации, чтобы количество повторных попыток можно было изменить без повторного развёртывания."}],"answer":1,"explain":{"en":"Marco says he will 'add a comment in the code to explain why we only retry on those two status codes', matching option B.","ru":"Марко говорит, что «добавит комментарий в коде, объясняющий, почему мы повторяем попытки только при этих двух кодах статуса», что соответствует варианту Б."}}],"targetWords":["ngsl:0829","ngsl:0834","ngsl:0837","ngsl:0838","ngsl:0847","ngsl:0850"]},
  {"id":"b1e-sprint-retro","level":"B1","stream":"engineering","title":{"en":"Sprint 24 Retrospective Notes","ru":"Заметки по ретроспективе спринта 24"},"blurb":{"en":"Short notes from a two-week sprint retrospective at a small engineering team — what went well, what went wrong, and the action items they agreed to try next sprint.","ru":"Краткие заметки по ретроспективе двухнедельного спринта небольшой команды разработчиков — что прошло хорошо, что пошло не так и какие задачи они согласились попробовать в следующем спринте."},"source":{"en":"Internal team wiki page (retrospective template)","ru":"Внутренняя страница командной вики (шаблон ретроспективы)"},"passages":[{"en":"Sprint 24 ran from May 5 to May 16. The team completed eight out of ten planned tickets. Two tickets moved to the next sprint because the back-end API they depended on was not ready in time. Overall velocity was 34 story points, which is slightly above our average of 31.","ru":"Спринт 24 проходил с 5 по 16 мая. Команда выполнила восемь из десяти запланированных тикетов. Два тикета перешли в следующий спринт, потому что бэкенд-API, от которого они зависели, не был готов вовремя. Общая скорость составила 34 стори-пойнта, что немного выше среднего показателя в 31.","words":[{"id":"b1e-sprint-retro-w1","w":"sprint","ru":"спринт","gloss":"a fixed short period (usually one or two weeks) in which a team completes a set of planned work","pos":"noun","ipa":"sprɪnt","example":"We plan which features to build at the start of each sprint."},{"id":"b1e-sprint-retro-w2","w":"ticket","ru":"тикет (задача в трекере)","gloss":"a work item recorded in a task-tracking tool such as Jira or Linear","pos":"noun","ipa":"ˈtɪkɪt","example":"Please create a ticket for every bug you find before fixing it."},{"id":"b1e-sprint-retro-w3","w":"velocity","ru":"скорость (командная)","gloss":"the amount of work a team completes in one sprint, measured in story points","pos":"noun","ipa":"vɪˈlɒsɪti","example":"Tracking velocity helps the team predict how much work fits in the next sprint."},{"id":"b1e-sprint-retro-w4","w":"story points","ru":"стори-пойнты (очки сложности)","gloss":"a unit teams use to estimate how much effort a task requires, not how many hours it takes","pos":"phrase","example":"The team gave the new feature eight story points because it touched three services."}]},{"en":"What went well: the daily standups stayed short — under fifteen minutes every day. The new CI pipeline caught two regressions before they reached the staging environment, which saved the team significant debugging time. Pair programming on the payment module also helped — the code review was much faster because two people already understood the changes.","ru":"Что прошло хорошо: ежедневные стендапы оставались короткими — каждый день не более пятнадцати минут. Новый CI-пайплайн поймал две регрессии до того, как они достигли стейджинг-окружения, что сэкономило команде значительное время на отладку. Парное программирование в платёжном модуле также помогло — ревью кода прошло гораздо быстрее, потому что два человека уже понимали изменения.","words":[{"id":"b1e-sprint-retro-w5","w":"standup","ru":"стендап (ежедневная встреча)","gloss":"a short daily meeting where each team member says what they did, what they plan to do, and whether anything is blocking them","pos":"noun","ipa":"ˈstændʌp","example":"Keep the standup focused — save long discussions for after the meeting."},{"id":"b1e-sprint-retro-w6","w":"CI pipeline","ru":"CI-пайплайн (непрерывная интеграция)","gloss":"an automated sequence of steps (build, test, lint) that runs every time code is pushed to the repository","pos":"phrase","example":"The CI pipeline failed because one unit test was not passing."},{"id":"b1e-sprint-retro-w7","w":"regression","ru":"регрессия (новая ошибка)","gloss":"a bug introduced by a recent change that breaks something that was working before","pos":"noun","ipa":"rɪˈɡreʃən","example":"Run the full test suite after every merge to detect regressions early."},{"id":"b1e-sprint-retro-w8","w":"staging environment","ru":"стейджинг-окружение","gloss":"a test server that closely mirrors production, used to verify changes before releasing them to real users","pos":"phrase","example":"Always test a new feature in the staging environment before deploying to production."},{"id":"b1e-sprint-retro-w9","w":"pair programming","ru":"парное программирование","gloss":"a practice where two developers work together at one computer — one writes code while the other reviews in real time","pos":"phrase","example":"We used pair programming to onboard the new developer faster."}]},{"en":"What did not go well: the two unfinished tickets were a problem. The back-end team did not tell us that the API would be delayed until day eight of the sprint. This late communication blocked our front-end engineers for almost a week. We also had one deploy that failed in production and had to be rolled back — the cause was a missing environment variable that our tests did not cover.","ru":"Что пошло не так: два незавершённых тикета стали проблемой. Команда бэкенда не сообщила нам о задержке API до восьмого дня спринта. Это позднее сообщение заблокировало наших фронтенд-разработчиков почти на неделю. Кроме того, один деплой упал на продакшене и пришлось выполнить откат — причиной стала отсутствующая переменная окружения, которую наши тесты не проверяли.","words":[{"id":"b1e-sprint-retro-w10","w":"rolled back","ru":"откатить (вернуть предыдущую версию)","gloss":"to undo a deployment and return to the previous working version of the software","pos":"phrase","example":"We rolled back the release after users reported that the checkout page was broken."},{"id":"b1e-sprint-retro-w11","w":"environment variable","ru":"переменная окружения","gloss":"a named value stored outside the code (e.g. in the server config) that controls application behaviour such as database URLs or secret keys","pos":"phrase","example":"Store the database password as an environment variable, never in source code."}]},{"en":"Action items for Sprint 25: (1) The back-end team will post a status update in the shared Slack channel by day three if any dependency is at risk. (2) We will add a check for required environment variables to the deployment script. (3) The team agreed to try test-driven development on the next complex task to reduce the chance of regressions. We will review whether these actions helped at the end of Sprint 25.","ru":"Задачи для спринта 25: (1) Команда бэкенда будет публиковать обновление статуса в общем Slack-канале к третьему дню, если любая зависимость под угрозой. (2) Мы добавим проверку обязательных переменных окружения в скрипт деплоя. (3) Команда договорилась попробовать разработку через тестирование для следующей сложной задачи, чтобы снизить вероятность регрессий. Мы проверим, помогли ли эти действия, в конце спринта 25.","words":[{"id":"b1e-sprint-retro-w12","w":"action item","ru":"задача по итогам встречи","gloss":"a specific thing someone agrees to do after a meeting, with a clear owner and deadline","pos":"phrase","example":"Write down every action item before the meeting ends so nothing is forgotten."},{"id":"b1e-sprint-retro-w13","w":"dependency","ru":"зависимость","gloss":"something your work relies on — another team's output, a library, or an external service","pos":"noun","ipa":"dɪˈpendənsi","example":"Identify every external dependency before committing to a deadline."},{"id":"b1e-sprint-retro-w14","w":"test-driven development","ru":"разработка через тестирование (TDD)","gloss":"a practice where you write a failing test first, then write only the code needed to make it pass","pos":"phrase","example":"Test-driven development forces you to think about the expected behaviour before you write a single line of implementation."}]},{"en":"Overall, Sprint 24 was a solid sprint despite the two blocked tickets. The team morale was good — three team members said in the survey that they felt well supported. The main lesson is that communication about risks must happen earlier. If we know a dependency is delayed on day three instead of day eight, we can re-plan and stay productive.","ru":"В целом спринт 24 был крепким, несмотря на два заблокированных тикета. Моральный дух команды был высоким — трое участников в опросе ответили, что чувствовали достаточную поддержку. Главный урок: о рисках нужно сообщать раньше. Если мы узнаем о задержке зависимости на третий день, а не на восьмой, мы сможем перепланировать и оставаться продуктивными.","words":[{"id":"b1e-sprint-retro-w15","w":"morale","ru":"моральный дух","gloss":"the confidence, enthusiasm, and satisfaction felt by a person or group at work","pos":"noun","ipa":"məˈrɑːl","example":"Celebrating small wins helps keep team morale high during a long project."},{"id":"b1e-sprint-retro-w16","w":"re-plan","ru":"перепланировать","gloss":"to change the plan when circumstances change, redistributing tasks to keep the sprint on track","pos":"verb","example":"When a key engineer called in sick, we had to re-plan the sprint on day two."}]}],"phrases":[{"id":"b1e-sprint-retro-p1","en":"what went well","ru":"что прошло хорошо","note":{"en":"A standard retrospective section heading asking the team to name positive things from the sprint.","ru":"Стандартный раздел ретроспективы, в котором команда называет позитивные моменты спринта."}},{"id":"b1e-sprint-retro-p2","en":"move to the next sprint","ru":"перенести в следующий спринт","note":{"en":"To take an unfinished ticket out of the current sprint and put it in the backlog for the next one.","ru":"Перенести незавершённый тикет из текущего спринта в бэклог следующего."}},{"id":"b1e-sprint-retro-p3","en":"blocked by","ru":"заблокировано из-за","note":{"en":"Unable to progress because something else (a dependency, a decision, another team) is not yet ready.","ru":"Невозможно продвигаться вперёд, потому что что-то другое (зависимость, решение, другая команда) ещё не готово."}},{"id":"b1e-sprint-retro-p4","en":"at risk","ru":"под угрозой (может не уложиться в срок)","note":{"en":"Likely to be delayed or fail unless action is taken soon.","ru":"Вероятно, будет задержано или провалится, если не принять меры вовремя."}}],"questions":[{"id":"b1e-sprint-retro-q1","q":{"en":"Why did two tickets move to Sprint 25?","ru":"Почему два тикета перешли в спринт 25?"},"options":[{"en":"The back-end API they needed was not finished in time.","ru":"Необходимый бэкенд-API не был готов вовремя."},{"en":"The front-end engineers were sick for several days.","ru":"Фронтенд-разработчики несколько дней болели."},{"en":"The team decided to reduce the sprint workload on purpose.","ru":"Команда намеренно решила снизить нагрузку спринта."}],"answer":0,"explain":{"en":"The text says the two tickets were not completed because 'the back-end API they depended on was not ready in time.'","ru":"В тексте сказано, что два тикета не были выполнены, потому что «бэкенд-API, от которого они зависели, не был готов вовремя»."}},{"id":"b1e-sprint-retro-q2","q":{"en":"What caused the failed production deployment?","ru":"Что вызвало сбой деплоя на продакшене?"},"options":[{"en":"A regression introduced by a merge conflict.","ru":"Регрессия, вызванная конфликтом при слиянии."},{"en":"A missing environment variable that tests did not check.","ru":"Отсутствующая переменная окружения, которую тесты не проверяли."},{"en":"The staging environment was configured incorrectly.","ru":"Стейджинг-окружение было настроено неверно."}],"answer":1,"explain":{"en":"The text says the deploy 'had to be rolled back — the cause was a missing environment variable that our tests did not cover.'","ru":"В тексте говорится, что деплой «пришлось откатить — причиной стала отсутствующая переменная окружения, которую наши тесты не проверяли»."}},{"id":"b1e-sprint-retro-q3","q":{"en":"Which action item directly addresses the late communication problem?","ru":"Какая задача напрямую решает проблему позднего информирования?"},"options":[{"en":"Try test-driven development on the next complex task.","ru":"Попробовать разработку через тестирование для следующей сложной задачи."},{"en":"Add a check for required environment variables to the deployment script.","ru":"Добавить проверку обязательных переменных окружения в скрипт деплоя."},{"en":"The back-end team will post a status update by day three if any dependency is at risk.","ru":"Команда бэкенда будет публиковать обновление статуса к третьему дню, если зависимость под угрозой."}],"answer":2,"explain":{"en":"The late communication was the core problem: the team only learned about the API delay on day eight. The action item requiring a day-three status update directly fixes this.","ru":"Позднее информирование было основной проблемой: команда узнала о задержке API лишь на восьмой день. Задача с обновлением статуса к третьему дню напрямую это исправляет."}},{"id":"b1e-sprint-retro-q4","q":{"en":"What does the team plan to check at the end of Sprint 25?","ru":"Что команда планирует проверить в конце спринта 25?"},"options":[{"en":"Whether the team's velocity improved above 40 story points.","ru":"Выросла ли скорость команды выше 40 стори-пойнтов."},{"en":"Whether the three action items from Sprint 24 actually helped.","ru":"Действительно ли три задачи из спринта 24 помогли."},{"en":"Whether the back-end API is fully complete.","ru":"Полностью ли готов бэкенд-API."}],"answer":1,"explain":{"en":"The last paragraph says: 'We will review whether these actions helped at the end of Sprint 25.'","ru":"В последнем абзаце сказано: «Мы проверим, помогли ли эти действия, в конце спринта 25»."}}],"targetWords":["ngsl:0853","ngsl:1039","ngsl:1495"]},
  {"id":"b1e-system-design","level":"B1","stream":"engineering","title":{"en":"How Should We Build the Rate Limiter?","ru":"Как нам построить ограничитель запросов?"},"blurb":{"en":"A short discussion between two engineers weighing design options for a rate limiter — a system that controls how many requests a client can make in a given time window.","ru":"Короткое обсуждение двух инженеров, рассматривающих варианты дизайна для ограничителя запросов — системы, которая контролирует, сколько запросов клиент может сделать за заданный промежуток времени."},"source":{"en":"Engineering team design discussion (chat transcript)","ru":"Обсуждение дизайна инженерной командой (транскрипт чата)"},"passages":[{"en":"Maya: We need a rate limiter for the public API. Right now any client can send thousands of requests per second and it slows down the whole system for everyone. I looked at two main options: a fixed window counter and a sliding window counter. Which one do you think we should use?","ru":"Майя: Нам нужен ограничитель запросов для публичного API. Сейчас любой клиент может отправлять тысячи запросов в секунду, и это замедляет всю систему для всех. Я рассмотрела два основных варианта: счётчик фиксированного окна и счётчик скользящего окна. Какой, по-твоему, стоит использовать?","words":[{"id":"b1e-system-design-w1","w":"rate limiter","ru":"ограничитель запросов","gloss":"a component that blocks or delays requests when a client sends too many in a short time","pos":"phrase","example":"The rate limiter returned HTTP 429 when the client exceeded 100 requests per minute."},{"id":"b1e-system-design-w2","w":"fixed window counter","ru":"счётчик фиксированного окна","gloss":"a rate-limiting method that resets the request count at fixed clock intervals, e.g. every 60 seconds from the top of the minute","pos":"phrase","example":"With a fixed window counter, a client can burst up to the full limit right at the window boundary."},{"id":"b1e-system-design-w3","w":"sliding window counter","ru":"счётчик скользящего окна","gloss":"a rate-limiting method that counts requests in the most recent N seconds, moving forward in time rather than resetting at fixed intervals","pos":"phrase","example":"A sliding window counter gives smoother traffic control than a fixed window."}]},{"en":"Carlos: The fixed window is simpler to implement and uses less memory — you just store one integer per client per window. But it has a known problem: a client can send double the allowed requests by bursting right before and right after the window resets. For a public API that could be a real issue.","ru":"Карлос: Фиксированное окно проще реализовать и использует меньше памяти — нужно хранить всего одно целое число на клиента на окно. Но у него есть известная проблема: клиент может отправить вдвое больше разрешённых запросов, делая всплеск прямо перед сбросом окна и сразу после него. Для публичного API это может быть реальной проблемой.","words":[{"id":"b1e-system-design-w4","w":"implement","ru":"реализовать; внедрить","gloss":"to build or add a feature so that it actually works in the system","pos":"verb","ipa":"ˈɪmplɪment","example":"It took two days to implement the caching layer."},{"id":"b1e-system-design-w5","w":"burst","ru":"всплеск (запросов)","gloss":"a sudden short period of very high traffic where many requests arrive at almost the same time","pos":"noun","ipa":"bɜːst","example":"A burst of traffic after a social media post crashed the server."},{"id":"b1e-system-design-w6","w":"resets","ru":"сбрасывается","gloss":"returns to its starting value, usually zero, after a time interval ends","pos":"verb","example":"The counter resets to zero at the start of each minute."}]},{"en":"Maya: Right, that boundary burst is the classic weakness. The sliding window avoids it because the count always reflects the last 60 seconds, not a fixed clock slot. The trade-off is that we need to store a timestamp for every request, which uses more memory. For most clients that is fine, but if we have millions of clients it could add up.","ru":"Майя: Верно, граничный всплеск — это классическая слабость. Скользящее окно избегает этого, потому что счётчик всегда отражает последние 60 секунд, а не фиксированный временной слот. Компромисс в том, что нам нужно хранить временную метку для каждого запроса, что занимает больше памяти. Для большинства клиентов это нормально, но если у нас миллионы клиентов, это может накапливаться.","words":[{"id":"b1e-system-design-w7","w":"trade-off","ru":"компромисс; баланс","gloss":"a situation where gaining one benefit requires accepting a cost or limitation somewhere else","pos":"noun","ipa":"ˈtreɪdɒf","example":"The trade-off between consistency and availability is central to distributed system design."},{"id":"b1e-system-design-w8","w":"timestamp","ru":"временная метка","gloss":"a recorded date and time marking when an event happened","pos":"noun","ipa":"ˈtaɪmstæmp","example":"Every log line includes a timestamp so you can reconstruct the sequence of events."},{"id":"b1e-system-design-w9","w":"add up","ru":"накапливаться; суммироваться","gloss":"to grow to a significant total over many instances","pos":"phrase","example":"Small memory leaks add up and eventually crash the process."}]},{"en":"Carlos: How many active clients do we expect? If it is under a hundred thousand, the memory cost of the sliding window is probably acceptable. We could store the timestamps in Redis with a sorted set — each client gets one key, and we remove old entries with a range delete. That keeps the memory bounded per client.","ru":"Карлос: Сколько активных клиентов мы ожидаем? Если меньше ста тысяч, затраты памяти для скользящего окна, вероятно, приемлемы. Мы можем хранить временные метки в Redis с отсортированным множеством — каждый клиент получает один ключ, а старые записи удаляем через range delete. Это ограничивает потребление памяти на клиента.","words":[{"id":"b1e-system-design-w10","w":"Redis","ru":"Redis (база данных в памяти)","gloss":"an in-memory data store used for caching, session storage, and fast counters; data lives in RAM so reads and writes are very fast","pos":"noun","ipa":"ˈredɪs","example":"We store session tokens in Redis because reads need to be under one millisecond."},{"id":"b1e-system-design-w11","w":"sorted set","ru":"отсортированное множество","gloss":"a Redis data structure that stores unique values each with a numeric score; items are always ordered by score","pos":"phrase","example":"We used a sorted set with the timestamp as the score to find all requests in the last minute."},{"id":"b1e-system-design-w12","w":"bounded","ru":"ограниченный (по объёму)","gloss":"limited to a maximum size or amount that does not grow without control","pos":"adj","ipa":"ˈbaʊndɪd","example":"A bounded queue drops the oldest item when it is full, keeping memory usage predictable."}]},{"en":"Maya: Good point. Let us go with the sliding window and Redis sorted sets. I will write the design doc today. One more thing — should the limit apply per IP address or per API key? Per IP is easier but less accurate: many users can share one IP behind a company firewall. Per API key is more fair but requires clients to authenticate first.","ru":"Майя: Хорошее замечание. Давайте используем скользящее окно с отсортированными множествами Redis. Я напишу документ по дизайну сегодня. Ещё один момент — лимит должен применяться по IP-адресу или по API-ключу? По IP проще, но менее точно: многие пользователи могут использовать один IP за корпоративным фаерволом. По API-ключу справедливее, но требует, чтобы клиенты сначала прошли аутентификацию.","words":[{"id":"b1e-system-design-w13","w":"IP address","ru":"IP-адрес","gloss":"a unique numerical label assigned to each device on a network, used to identify and locate it","pos":"phrase","ipa":"ˌaɪ ˈpiː ˈædrɛs","example":"The server logs record the IP address of every incoming request."},{"id":"b1e-system-design-w14","w":"API key","ru":"API-ключ","gloss":"a secret token a client sends with each request to prove its identity and gain access to an API","pos":"phrase","example":"Rotate your API key immediately if you suspect it has been leaked."},{"id":"b1e-system-design-w15","w":"authenticate","ru":"аутентифицироваться; подтвердить личность","gloss":"to prove who you are to a system, usually by providing a password, token, or certificate","pos":"verb","ipa":"ɔːˈθentɪkeɪt","example":"Clients must authenticate before they can call any protected endpoint."}]}],"phrases":[{"id":"b1e-system-design-p1","en":"design doc","ru":"документ по дизайну (техническое задание)","note":{"en":"A short written document that describes a proposed technical solution, its trade-offs, and the decision made, shared with the team before implementation begins.","ru":"Короткий письменный документ, описывающий предлагаемое техническое решение, его компромиссы и принятое решение; передаётся команде до начала реализации."}},{"id":"b1e-system-design-p2","en":"per client","ru":"на клиента (отдельно для каждого)","note":{"en":"Applied individually to each client rather than shared across all clients; used when describing limits or counters.","ru":"Применяется отдельно к каждому клиенту, а не общее для всех; используется при описании лимитов или счётчиков."}},{"id":"b1e-system-design-p3","en":"add up","ru":"накапливаться; в сумме составлять значительную величину","note":{"en":"Used to warn that individually small costs (memory, latency, debt) can become large when multiplied by many instances.","ru":"Используется для предупреждения о том, что небольшие по отдельности затраты (память, задержка, долг) могут стать большими при умножении на множество экземпляров."}},{"id":"b1e-system-design-p4","en":"go with","ru":"выбрать; остановиться на","note":{"en":"Informal: to choose an option after discussing alternatives.","ru":"Разговорное: выбрать вариант после обсуждения альтернатив."}}],"questions":[{"id":"b1e-system-design-q1","q":{"en":"What is the main weakness of the fixed window counter approach?","ru":"В чём главный недостаток подхода с фиксированным окном?"},"options":[{"en":"It uses too much memory to store timestamps for each request.","ru":"Он использует слишком много памяти для хранения временных меток каждого запроса."},{"en":"A client can send double the allowed requests by bursting at the window boundary.","ru":"Клиент может отправить вдвое больше разрешённых запросов, делая всплеск на границе окна."},{"en":"It requires clients to have an API key before making any request.","ru":"Для выполнения запросов клиентам требуется API-ключ."}],"answer":1,"explain":{"en":"Carlos explains: 'a client can send double the allowed requests by bursting right before and right after the window resets.'","ru":"Карлос объясняет: «клиент может отправить вдвое больше разрешённых запросов, делая всплеск прямо перед сбросом окна и сразу после него»."}},{"id":"b1e-system-design-q2","q":{"en":"Why does the sliding window counter use more memory than the fixed window counter?","ru":"Почему счётчик скользящего окна использует больше памяти, чем счётчик фиксированного окна?"},"options":[{"en":"It stores a timestamp for every request, not just a single integer per window.","ru":"Он хранит временную метку для каждого запроса, а не просто одно целое число на окно."},{"en":"It requires a separate Redis instance for each client.","ru":"Ему требуется отдельный экземпляр Redis для каждого клиента."},{"en":"It counts requests over a longer time period than the fixed window.","ru":"Он считает запросы за более длительный период, чем фиксированное окно."}],"answer":0,"explain":{"en":"Maya says: 'we need to store a timestamp for every request, which uses more memory' — compared to the fixed window which stores just one integer per client.","ru":"Майя говорит: «нам нужно хранить временную метку для каждого запроса, что занимает больше памяти» — в отличие от фиксированного окна, которое хранит лишь одно целое число на клиента."}},{"id":"b1e-system-design-q3","q":{"en":"What data structure does Carlos suggest for storing the sliding window data in Redis?","ru":"Какую структуру данных Карлос предлагает для хранения данных скользящего окна в Redis?"},"options":[{"en":"A hash map with one field per minute.","ru":"Хэш-мап с одним полем на минуту."},{"en":"A sorted set with request timestamps as scores.","ru":"Отсортированное множество с временными метками запросов в качестве баллов."},{"en":"A simple string counter that increments on each request.","ru":"Простой строковый счётчик, увеличивающийся при каждом запросе."}],"answer":1,"explain":{"en":"Carlos says: 'We could store the timestamps in Redis with a sorted set — each client gets one key, and we remove old entries with a range delete.'","ru":"Карлос говорит: «Мы можем хранить временные метки в Redis с отсортированным множеством — каждый клиент получает один ключ, а старые записи удаляем через range delete»."}},{"id":"b1e-system-design-q4","q":{"en":"What is the downside of limiting by IP address instead of by API key?","ru":"Каков недостаток ограничения по IP-адресу вместо по API-ключу?"},"options":[{"en":"IP-based limits are harder to implement than API key limits.","ru":"Ограничения по IP сложнее реализовать, чем ограничения по API-ключу."},{"en":"Many users behind a company firewall share one IP, so the limit is less accurate.","ru":"Многие пользователи за корпоративным фаерволом используют один IP, поэтому лимит менее точен."},{"en":"IP addresses change too frequently to track reliably.","ru":"IP-адреса меняются слишком часто, чтобы их надёжно отслеживать."}],"answer":1,"explain":{"en":"Maya says: 'Per IP is easier but less accurate: many users can share one IP behind a company firewall.'","ru":"Майя говорит: «По IP проще, но менее точно: многие пользователи могут использовать один IP за корпоративным фаерволом»."}}],"targetWords":["ngsl:0859","ngsl:1009","ngsl:1018","ngsl:1116","ngsl:1453"]},
  {"id":"b1e-debugging-story","level":"B1","stream":"engineering","title":{"en":"The Midnight Memory Leak","ru":"Утечка памяти в полночь"},"blurb":{"en":"A backend engineer describes how she tracked down a slow memory leak that only appeared in production and how a single wrong assumption made the hunt much harder.","ru":"Бэкенд-разработчик рассказывает, как она отследила медленную утечку памяти, которая проявлялась только в продакшене, и как одно неверное предположение сильно усложнило поиск."},"source":{"en":"Engineering team blog post","ru":"Пост в блоге команды разработки"},"passages":[{"en":"Three weeks ago our production service started using more and more memory every hour. It did not crash immediately, but after about eight hours the process would run out of memory and restart. Users saw a brief error page, and the on-call engineer got an alert at two in the morning. I was that engineer.","ru":"Три недели назад наш продакшен-сервис начал потреблять всё больше памяти каждый час. Он не падал сразу, но примерно через восемь часов процесс исчерпывал память и перезапускался. Пользователи видели короткую страницу с ошибкой, а дежурный инженер получал алерт в два часа ночи. Этим инженером была я.","words":[{"id":"b1e-debugging-story-w1","w":"production","ru":"продакшен","gloss":"the live system that real users interact with, as opposed to a test environment","pos":"noun","ipa":"prəˈdʌkʃən","example":"We never test untested code directly in production."},{"id":"b1e-debugging-story-w2","w":"memory leak","ru":"утечка памяти","gloss":"a bug where a program keeps allocating memory but never frees it, causing RAM usage to grow over time","pos":"phrase","example":"A memory leak can run for hours before the process finally crashes."},{"id":"b1e-debugging-story-w3","w":"on-call","ru":"дежурный (on-call)","gloss":"an engineer who must respond to alerts at any hour when a system has a problem","pos":"adj","example":"The on-call engineer was paged at 3 a.m. when the server went down."},{"id":"b1e-debugging-story-w4","w":"alert","ru":"алерт; уведомление о проблеме","gloss":"an automatic notification sent when a metric crosses a danger threshold","pos":"noun","ipa":"əˈlɜːt","example":"We set an alert for when CPU usage stays above 90% for five minutes."}]},{"en":"My first step was to identify which part of the code was causing the problem. I added detailed logging and watched the metrics dashboard. The memory grew slowly and steadily — about two megabytes per minute. This made me think the leak was inside the request handler, because requests were coming in at a steady rate. I was wrong.","ru":"Первым делом мне нужно было определить, какая часть кода вызывает проблему. Я добавила подробное логирование и следила за дашбордом метрик. Память росла медленно и равномерно — около двух мегабайт в минуту. Это заставило меня думать, что утечка находится внутри обработчика запросов, так как запросы поступали с постоянной скоростью. Я ошибалась.","words":[{"id":"b1e-debugging-story-w5","w":"identify","ru":"определить; выявить","gloss":"to find and name the exact source of a problem","pos":"verb","ipa":"aɪˈdentɪfaɪ","example":"We need to identify the root cause before we apply any fix."},{"id":"b1e-debugging-story-w6","w":"logging","ru":"логирование","gloss":"the practice of writing messages from a running program to a file or console so you can read them later","pos":"noun","example":"Good logging made it easy to see which function was called first."},{"id":"b1e-debugging-story-w7","w":"metrics dashboard","ru":"дашборд метрик","gloss":"a web page that shows live charts for things like memory use, CPU, and request count","pos":"phrase","example":"The metrics dashboard showed a spike in latency at midnight."},{"id":"b1e-debugging-story-w8","w":"request handler","ru":"обработчик запросов","gloss":"the function in a server that runs when an HTTP request arrives and builds the response","pos":"phrase","example":"Each request handler reads the URL, calls the database, and returns JSON."}]},{"en":"After two hours of reading the wrong code, a colleague suggested I check the background job scheduler. We had a job that ran every ten seconds to clean up expired sessions. I looked at the code and found the error: the job was adding items to a list but never removing them. Each run made the list a little longer. That was the leak.","ru":"После двух часов изучения не того кода коллега предложил мне проверить планировщик фоновых задач. У нас была задача, которая запускалась каждые десять секунд для очистки истёкших сессий. Я посмотрела на код и нашла ошибку: задача добавляла элементы в список, но никогда их не удаляла. При каждом запуске список становился чуть длиннее. Это и была утечка.","words":[{"id":"b1e-debugging-story-w9","w":"background job","ru":"фоновая задача","gloss":"a task the server runs automatically on a schedule, not triggered by a user request","pos":"phrase","example":"A background job sends the daily report email at 6 a.m."},{"id":"b1e-debugging-story-w10","w":"scheduler","ru":"планировщик","gloss":"a component that starts jobs at fixed times or intervals automatically","pos":"noun","ipa":"ˈʃedjuːlə","example":"The scheduler triggers a database backup every night at midnight."},{"id":"b1e-debugging-story-w11","w":"expired session","ru":"истёкшая сессия","gloss":"a user login token that has passed its time limit and is no longer valid","pos":"phrase","example":"The cleanup job deletes expired sessions to keep the database small."},{"id":"b1e-debugging-story-w12","w":"error","ru":"ошибка","gloss":"a mistake in code that causes the program to behave incorrectly","pos":"noun","ipa":"ˈerə","example":"The error was a missing null check in the parser."}]},{"en":"The fix was small — just three lines of code to clear the list at the end of each job run. I deployed the fix to production, watched the memory graph level off, and went to sleep. The lesson I took away: when memory grows at a constant rate, look at code that runs on a fixed schedule, not code that runs per request. Next time I will check that first.","ru":"Исправление оказалось небольшим — всего три строки кода для очистки списка в конце каждого запуска задачи. Я задеплоила исправление в продакшен, наблюдала, как график памяти выровнялся, и пошла спать. Урок, который я вынесла: когда память растёт с постоянной скоростью, ищи код, который выполняется по расписанию, а не код, который работает на каждый запрос. В следующий раз я проверю это первым делом.","words":[{"id":"b1e-debugging-story-w13","w":"fix","ru":"исправление; фикс","gloss":"a code change that solves a bug","pos":"noun","ipa":"fɪks","example":"The one-line fix stopped the server from crashing under load."},{"id":"b1e-debugging-story-w14","w":"deploy","ru":"деплоить; выпускать в работу","gloss":"to release a new version of code so that it runs on the live server","pos":"verb","ipa":"dɪˈplɔɪ","example":"We deploy to production every Friday afternoon after all tests pass."},{"id":"b1e-debugging-story-w15","w":"constant rate","ru":"постоянная скорость","gloss":"a value that increases or changes by the same amount every unit of time","pos":"phrase","example":"Memory growing at a constant rate usually means a scheduled job is leaking."}]},{"en":"Looking back, the incident taught me that assumptions are dangerous. I assumed the problem was in the request handler because that is the most common place for performance bugs. That assumption cost me two hours. Good debugging means testing assumptions early, not confirming them. Start with the simplest possible cause and rule it out before moving to complex ones.","ru":"Оглядываясь назад, этот инцидент научил меня, что предположения опасны. Я предположила, что проблема в обработчике запросов, потому что это наиболее распространённое место для ошибок производительности. Это предположение стоило мне двух часов. Хорошая отладка означает раннюю проверку предположений, а не их подтверждение. Начинай с самой простой возможной причины и исключай её, прежде чем переходить к сложным.","words":[{"id":"b1e-debugging-story-w16","w":"incident","ru":"инцидент","gloss":"an unexpected event in a running system that requires investigation and a fix","pos":"noun","ipa":"ˈɪnsɪdənt","example":"The team wrote a post-mortem report after the incident."},{"id":"b1e-debugging-story-w17","w":"assumption","ru":"предположение","gloss":"something you believe to be true without checking it first","pos":"noun","ipa":"əˈsʌmpʃən","example":"His assumption that the database was slow turned out to be wrong."},{"id":"b1e-debugging-story-w18","w":"rule out","ru":"исключить","gloss":"to prove that a possible cause is not responsible, so you can focus on others","pos":"phrase","example":"We ran a quick load test to rule out a network problem."}]}],"phrases":[{"id":"b1e-debugging-story-p1","en":"run out of memory","ru":"исчерпать память","note":{"en":"When a process has used all the RAM the operating system allows, it crashes or is killed.","ru":"Когда процесс использует всю доступную оперативную память, он падает или принудительно завершается операционной системой."}},{"id":"b1e-debugging-story-p2","en":"level off","ru":"выровняться; стабилизироваться","note":{"en":"When a rising graph stops climbing and becomes flat, engineers say it has 'levelled off' — a good sign after a fix.","ru":"Когда растущий график перестаёт подниматься и становится ровным, инженеры говорят, что он «выровнялся» — хороший знак после исправления."}},{"id":"b1e-debugging-story-p3","en":"root cause","ru":"первопричина","note":{"en":"The original, deepest reason why a bug or outage happened — fixing it prevents the problem from returning.","ru":"Исходная, глубинная причина возникновения бага или сбоя — устранив её, вы предотвращаете повторение проблемы."}},{"id":"b1e-debugging-story-p4","en":"take away","ru":"вынести урок; запомнить","note":{"en":"Used when summarising the main lesson learned from an experience: 'The takeaway is…'","ru":"Используется при подведении итогов опыта: «Главный урок здесь…»"}}],"questions":[{"id":"b1e-debugging-story-q1","q":{"en":"What was the immediate symptom that triggered the on-call alert?","ru":"Какой симптом немедленно вызвал алерт дежурному инженеру?"},"options":[{"en":"The service crashed after about eight hours due to running out of memory.","ru":"Сервис падал примерно через восемь часов из-за нехватки памяти."},{"en":"The request handler started returning errors immediately on startup.","ru":"Обработчик запросов начал возвращать ошибки сразу при запуске."},{"en":"The background job scheduler stopped running entirely.","ru":"Планировщик фоновых задач полностью прекратил работу."}],"answer":0,"explain":{"en":"The text says 'after about eight hours the process would run out of memory and restart', which is what caused the alert.","ru":"В тексте сказано: «примерно через восемь часов процесс исчерпывал память и перезапускался» — именно это и вызывало алерт."}},{"id":"b1e-debugging-story-q2","q":{"en":"Where did the engineer first look for the bug, and why was that a mistake?","ru":"Где инженер сначала искала баг и почему это оказалось ошибкой?"},"options":[{"en":"In the request handler, because memory grew at a rate that matched incoming requests — but the real cause was a scheduled job.","ru":"В обработчике запросов, потому что память росла с той же скоростью, что и входящие запросы, — но настоящей причиной была фоновая задача."},{"en":"In the database layer, because expired sessions were taking too much space there.","ru":"В слое базы данных, потому что истёкшие сессии занимали там слишком много места."},{"en":"In the logging configuration, because too many log lines were filling up RAM.","ru":"В конфигурации логирования, потому что слишком много строк лога заполняли оперативную память."}],"answer":0,"explain":{"en":"She looked at the request handler because requests came at a steady rate, matching the steady memory growth — but the real leak was in a background job that ran on a fixed schedule.","ru":"Она смотрела в обработчик запросов, потому что запросы поступали с постоянной скоростью, совпадая с равномерным ростом памяти. Но настоящая утечка была в фоновой задаче, запускавшейся по расписанию."}},{"id":"b1e-debugging-story-q3","q":{"en":"What was the actual bug that caused the memory leak?","ru":"Какой именно баг вызвал утечку памяти?"},"options":[{"en":"The database kept open connections that were never closed.","ru":"База данных держала открытые соединения, которые никогда не закрывались."},{"en":"A background job added items to a list every run but never removed them.","ru":"Фоновая задача добавляла элементы в список при каждом запуске, но никогда их не удаляла."},{"en":"The logging system wrote to an in-memory buffer that was never flushed.","ru":"Система логирования писала в буфер в памяти, который никогда не очищался."}],"answer":1,"explain":{"en":"The text states: 'the job was adding items to a list but never removing them. Each run made the list a little longer.'","ru":"В тексте сказано: «задача добавляла элементы в список, но никогда их не удаляла. При каждом запуске список становился чуть длиннее»."}},{"id":"b1e-debugging-story-q4","q":{"en":"What is the main lesson the engineer says she learned from this incident?","ru":"Какой главный урок, по словам инженера, она вынесла из этого инцидента?"},"options":[{"en":"Always add more logging before investigating a memory problem.","ru":"Всегда добавляй больше логирования перед расследованием проблем с памятью."},{"en":"Test assumptions early instead of confirming them; start with the simplest cause.","ru":"Проверяй предположения рано, а не подтверждай их; начинай с самой простой причины."},{"en":"Background jobs should always be disabled in production to prevent leaks.","ru":"Фоновые задачи всегда нужно отключать в продакшене во избежание утечек."}],"answer":1,"explain":{"en":"The final paragraph states: 'Good debugging means testing assumptions early, not confirming them. Start with the simplest possible cause.'","ru":"В последнем абзаце сказано: «Хорошая отладка означает раннюю проверку предположений, а не их подтверждение. Начинай с самой простой возможной причины»."}}],"targetWords":["ngsl:0805","ngsl:1495","ngsl:0972","ngsl:1805","ngsl:1931"]},
  {"id":"b1e-deprecation-notice","level":"B1","stream":"engineering","title":{"en":"Deprecation Notice: Legacy Auth API v1","ru":"Уведомление об устаревании: устаревший Auth API v1"},"blurb":{"en":"An official notice announcing that an old authentication API will be shut down, explaining the reasons, the timeline, and the steps teams must take to migrate to the new version.","ru":"Официальное уведомление о том, что старый API аутентификации будет отключён, с объяснением причин, сроков и шагов, которые команды должны предпринять для перехода на новую версию."},"source":{"en":"Internal developer platform notice","ru":"Внутреннее уведомление платформы для разработчиков"},"passages":[{"en":"**[NOTICE] Auth API v1 is deprecated — end-of-life: 2024-12-01**\n\nThis notice is for all teams that use the `/api/v1/auth` endpoints. These endpoints have been available since 2019 and have served the platform well. However, they were built before we introduced token rotation and multi-factor support, so they cannot provide the security guarantees we now require. After 2024-12-01, all requests to v1 endpoints will return a 410 Gone response. There will be no further extensions to this deadline.","ru":"**[УВЕДОМЛЕНИЕ] Auth API v1 устарел — дата отключения: 01.12.2024**\n\nДанное уведомление предназначено для всех команд, использующих эндпоинты `/api/v1/auth`. Эти эндпоинты доступны с 2019 года и хорошо служили платформе. Однако они были созданы до того, как мы ввели ротацию токенов и поддержку многофакторной аутентификации, поэтому они не могут обеспечить гарантии безопасности, которых мы сейчас требуем. После 01.12.2024 все запросы к эндпоинтам v1 будут возвращать ответ 410 Gone. Никаких дальнейших продлений этого срока не будет.","words":[{"id":"b1e-deprecation-notice-w1","w":"deprecated","ru":"устаревший; помеченный как устаревший","gloss":"officially marked as old and no longer recommended — developers should stop using it and switch to a newer alternative","pos":"adj","ipa":"ˈdeprəkeɪtɪd","example":"The deprecated function still works but will be removed in the next major release."},{"id":"b1e-deprecation-notice-w2","w":"end-of-life","ru":"конец жизненного цикла","gloss":"the date when a product or API stops being supported and will be shut down","pos":"phrase","example":"The library reached end-of-life, so the team switched to a maintained alternative."},{"id":"b1e-deprecation-notice-w3","w":"endpoint","ru":"эндпоинт; адрес API","gloss":"a specific URL in an API that handles one type of request, such as /api/users or /api/login","pos":"noun","ipa":"ˈendpɔɪnt","example":"The POST /login endpoint accepts a username and password and returns a token."},{"id":"b1e-deprecation-notice-w4","w":"token rotation","ru":"ротация токенов","gloss":"a security practice where authentication tokens are replaced with new ones after a short time, reducing the risk if a token is stolen","pos":"phrase","example":"Token rotation means a stolen token becomes useless within minutes."},{"id":"b1e-deprecation-notice-w5","w":"410 Gone","ru":"410 Gone (HTTP-статус)","gloss":"an HTTP status code meaning the requested resource has been permanently removed and will not come back","pos":"phrase","example":"The server returns 410 Gone when a client calls a deleted API endpoint."}]},{"en":"**Why are we removing v1?**\n\nThe v1 API issues long-lived tokens with no expiry. If a token is stolen, an attacker can use it forever. The v2 API uses short-lived access tokens (15 minutes) and long-lived refresh tokens with automatic rotation. This means a stolen token becomes useless quickly. We cannot add these security features to v1 without breaking its existing interface, so a clean replacement is the right approach.","ru":"**Почему мы удаляем v1?**\n\nAPI v1 выдаёт долгоживущие токены без срока действия. Если токен украден, злоумышленник может использовать его вечно. API v2 использует короткоживущие токены доступа (15 минут) и долгоживущие токены обновления с автоматической ротацией. Это означает, что украденный токен быстро становится бесполезным. Мы не можем добавить эти функции безопасности в v1, не нарушив его существующий интерфейс, поэтому чистая замена — правильный подход.","words":[{"id":"b1e-deprecation-notice-w6","w":"long-lived token","ru":"долгоживущий токен","gloss":"an authentication credential that stays valid for a long time — days, months, or forever — which is a security risk","pos":"phrase","example":"Long-lived tokens are convenient but dangerous if leaked."},{"id":"b1e-deprecation-notice-w7","w":"access token","ru":"токен доступа","gloss":"a short-lived credential the client sends with each request to prove it is allowed to use the API","pos":"phrase","example":"The access token expires in 15 minutes and must be refreshed using the refresh token."},{"id":"b1e-deprecation-notice-w8","w":"refresh token","ru":"токен обновления","gloss":"a separate, longer-lived credential used only to get a new access token when the old one expires","pos":"phrase","example":"The client stores the refresh token securely and uses it once the access token expires."},{"id":"b1e-deprecation-notice-w9","w":"replace","ru":"заменить","gloss":"to remove something old and put something new in its place","pos":"verb","ipa":"rɪˈpleɪs","example":"We will replace the v1 library with v2 before the deadline."}]},{"en":"**Migration steps**\n\nStep 1 — Update your client library. Replace `auth-sdk@1.x` with `auth-sdk@2.x` in your package dependencies. The v2 SDK handles token refresh automatically, so you do not need to manage it yourself.\n\nStep 2 — Change the base URL. Update all references from `/api/v1/auth` to `/api/v2/auth` in your configuration files. A global search-and-replace in your code editor is the fastest way to do this.","ru":"**Шаги миграции**\n\nШаг 1 — Обновите клиентскую библиотеку. Замените `auth-sdk@1.x` на `auth-sdk@2.x` в зависимостях вашего пакета. SDK v2 обрабатывает обновление токенов автоматически, так что вам не нужно управлять этим самостоятельно.\n\nШаг 2 — Измените базовый URL. Обновите все ссылки с `/api/v1/auth` на `/api/v2/auth` в ваших конфигурационных файлах. Глобальный поиск и замена в редакторе кода — самый быстрый способ сделать это.","words":[{"id":"b1e-deprecation-notice-w10","w":"migration","ru":"миграция; переход","gloss":"the process of moving from an old system, format, or API version to a new one","pos":"noun","ipa":"maɪˈɡreɪʃən","example":"The migration from PostgreSQL 13 to 15 took the team two sprint cycles."},{"id":"b1e-deprecation-notice-w11","w":"dependency","ru":"зависимость","gloss":"an external library or package that your project needs in order to run","pos":"noun","ipa":"dɪˈpendənsi","example":"We listed all outdated dependencies and updated them one by one."},{"id":"b1e-deprecation-notice-w12","w":"base URL","ru":"базовый URL","gloss":"the common beginning part of all API addresses, such as https://api.example.com/v2","pos":"phrase","example":"Changing the base URL in one config file updated all API calls at once."},{"id":"b1e-deprecation-notice-w13","w":"search-and-replace","ru":"поиск и замена","gloss":"a text editor feature that finds every occurrence of a word or string and replaces it with another","pos":"phrase","example":"Use search-and-replace to rename a variable across all files in the project."}]},{"en":"Step 3 — Test in staging first. Deploy the updated code to a staging environment and verify that login, token refresh, and logout all work correctly. Check that your error-handling code responds well to the new error formats returned by v2.\n\nStep 4 — Remove old credentials. After you confirm that v2 is working, delete any v1 API keys from your secrets store. Old keys will stop working after the deadline anyway, but removing them early is good security practice.","ru":"Шаг 3 — Сначала тестируйте в стейджинге. Разверните обновлённый код в стейджинг-окружении и убедитесь, что вход, обновление токена и выход работают корректно. Проверьте, что ваш код обработки ошибок правильно реагирует на новые форматы ошибок, возвращаемые v2.\n\nШаг 4 — Удалите старые учётные данные. После того как вы убедитесь, что v2 работает, удалите все ключи API v1 из вашего хранилища секретов. Старые ключи в любом случае перестанут работать после дедлайна, но удалить их раньше — хорошая практика безопасности.","words":[{"id":"b1e-deprecation-notice-w14","w":"staging environment","ru":"стейджинг-окружение","gloss":"a server that mirrors production but is not accessible to real users — used to test changes safely before going live","pos":"phrase","example":"We always deploy to staging first and run integration tests before touching production."},{"id":"b1e-deprecation-notice-w15","w":"error handling","ru":"обработка ошибок","gloss":"code that catches errors returned by a function or API and decides what to do — retry, show a message, or log and continue","pos":"phrase","example":"Good error handling shows the user a friendly message instead of a raw stack trace."},{"id":"b1e-deprecation-notice-w16","w":"secrets store","ru":"хранилище секретов","gloss":"a secure system for storing sensitive values like passwords and API keys so they are not kept in plain text in code","pos":"phrase","example":"Never put API keys in your code — use a secrets store instead."},{"id":"b1e-deprecation-notice-w17","w":"credentials","ru":"учётные данные","gloss":"a set of information (like a key, token, or username+password) that proves your identity to a system","pos":"noun","ipa":"krɪˈdenʃəlz","example":"Rotate your credentials immediately if you suspect they have been leaked."}]},{"en":"**Support and questions**\n\nIf you need help, open a ticket in the #platform-support Slack channel. We will resolve most questions within one business day. A full migration guide with code examples is available in the developer portal at `/docs/auth-v2-migration`. Teams that have not completed migration by 2024-11-01 will receive a direct reminder from the platform team. We encourage everyone to start early — do not wait until the final week.","ru":"**Поддержка и вопросы**\n\nЕсли вам нужна помощь, создайте тикет в Slack-канале #platform-support. Мы решим большинство вопросов в течение одного рабочего дня. Полное руководство по миграции с примерами кода доступно на портале разработчиков по адресу `/docs/auth-v2-migration`. Команды, не завершившие миграцию до 01.11.2024, получат прямое напоминание от команды платформы. Мы рекомендуем всем начать заранее — не ждите последней недели.","words":[{"id":"b1e-deprecation-notice-w18","w":"resolve","ru":"решить; урегулировать","gloss":"to fix a problem or answer a question so that it is no longer an issue","pos":"verb","ipa":"rɪˈzɒlv","example":"The support team resolved all open tickets before the end of the sprint."},{"id":"b1e-deprecation-notice-w19","w":"developer portal","ru":"портал для разработчиков","gloss":"a website where developers find documentation, API references, and guides for a platform","pos":"phrase","example":"The developer portal lists every endpoint, parameter, and error code."},{"id":"b1e-deprecation-notice-w20","w":"migration guide","ru":"руководство по миграции","gloss":"a document that explains step by step how to move from an old version of an API or system to a new one","pos":"phrase","example":"Follow the migration guide to update your code in the correct order."}]}],"phrases":[{"id":"b1e-deprecation-notice-p1","en":"breaking change","ru":"ломающее изменение","note":{"en":"A change in an API or library that causes existing code to stop working — callers must update their code to continue.","ru":"Изменение в API или библиотеке, из-за которого существующий код перестаёт работать — вызывающие стороны должны обновить свой код, чтобы продолжить работу."}},{"id":"b1e-deprecation-notice-p2","en":"end-of-life date","ru":"дата окончания поддержки","note":{"en":"The specific calendar date when an API, product, or software version will stop working or receiving updates.","ru":"Конкретная календарная дата, когда API, продукт или версия программного обеспечения прекратят работу или получение обновлений."}},{"id":"b1e-deprecation-notice-p3","en":"start early","ru":"начать заранее","note":{"en":"A common recommendation in migration notices — migrate well before the deadline to have time to fix unexpected problems.","ru":"Распространённая рекомендация в уведомлениях о миграции — мигрируйте задолго до дедлайна, чтобы было время исправить неожиданные проблемы."}},{"id":"b1e-deprecation-notice-p4","en":"good security practice","ru":"хорошая практика безопасности","note":{"en":"An action that reduces security risk even if not strictly required — for example, rotating old credentials before they expire.","ru":"Действие, снижающее риск безопасности, даже если оно строго не обязательно — например, ротация старых учётных данных до истечения срока их действия."}}],"questions":[{"id":"b1e-deprecation-notice-q1","q":{"en":"What will happen to requests sent to v1 endpoints after 2024-12-01?","ru":"Что произойдёт с запросами к эндпоинтам v1 после 01.12.2024?"},"options":[{"en":"They will be automatically redirected to the v2 endpoints.","ru":"Они будут автоматически перенаправлены на эндпоинты v2."},{"en":"They will return a 410 Gone response.","ru":"Они будут возвращать ответ 410 Gone."},{"en":"They will continue to work but with reduced security features.","ru":"Они продолжат работать, но с ограниченными функциями безопасности."}],"answer":1,"explain":{"en":"The notice states: 'all requests to v1 endpoints will return a 410 Gone response. There will be no further extensions.'","ru":"В уведомлении сказано: «все запросы к эндпоинтам v1 будут возвращать ответ 410 Gone. Никаких дальнейших продлений не будет»."}},{"id":"b1e-deprecation-notice-q2","q":{"en":"What is the main security reason for removing v1?","ru":"Какова главная причина безопасности для удаления v1?"},"options":[{"en":"v1 tokens can only be used from one IP address, which limits legitimate users.","ru":"Токены v1 можно использовать только с одного IP-адреса, что ограничивает легитимных пользователей."},{"en":"v1 issues tokens with no expiry, so a stolen token can be used forever.","ru":"v1 выдаёт токены без срока действия, поэтому украденный токен можно использовать вечно."},{"en":"v1 does not support HTTPS, making all traffic readable by attackers.","ru":"v1 не поддерживает HTTPS, что делает весь трафик читаемым для злоумышленников."}],"answer":1,"explain":{"en":"The notice explains: 'The v1 API issues long-lived tokens with no expiry. If a token is stolen, an attacker can use it forever.'","ru":"В уведомлении объясняется: «API v1 выдаёт долгоживущие токены без срока действия. Если токен украден, злоумышленник может использовать его вечно»."}},{"id":"b1e-deprecation-notice-q3","q":{"en":"According to the migration steps, what should teams do BEFORE deploying to production?","ru":"Согласно шагам миграции, что команды должны сделать ДО деплоя в продакшен?"},"options":[{"en":"Open a support ticket to get permission from the platform team.","ru":"Создать тикет поддержки, чтобы получить разрешение от команды платформы."},{"en":"Test the updated code in a staging environment first.","ru":"Сначала протестировать обновлённый код в стейджинг-окружении."},{"en":"Delete all v1 API keys from the secrets store.","ru":"Удалить все ключи API v1 из хранилища секретов."}],"answer":1,"explain":{"en":"Step 3 says: 'Deploy the updated code to a staging environment and verify that login, token refresh, and logout all work correctly' — this comes before production.","ru":"Шаг 3 гласит: «Разверните обновлённый код в стейджинг-окружении и убедитесь, что вход, обновление токена и выход работают корректно» — это делается до деплоя в продакшен."}},{"id":"b1e-deprecation-notice-q4","q":{"en":"Why does the notice recommend deleting old v1 API keys even though they will stop working automatically?","ru":"Почему уведомление рекомендует удалять старые ключи API v1, даже если они перестанут работать автоматически?"},"options":[{"en":"Because keeping unused credentials in a secrets store is a security risk.","ru":"Потому что хранение неиспользуемых учётных данных в хранилище секретов является угрозой безопасности."},{"en":"Because the secrets store will run out of space if old keys are not deleted.","ru":"Потому что хранилище секретов исчерпает место, если старые ключи не будут удалены."},{"en":"Because v1 keys can still be used after the deadline if they are in the secrets store.","ru":"Потому что ключи v1 всё ещё можно использовать после дедлайна, если они находятся в хранилище секретов."}],"answer":0,"explain":{"en":"The notice says 'removing them early is good security practice' — unused credentials in a secrets store are a risk if the store is ever compromised.","ru":"В уведомлении сказано: «удалить их раньше — хорошая практика безопасности» — неиспользуемые учётные данные в хранилище секретов представляют риск, если хранилище когда-либо будет скомпрометировано."}}],"targetWords":["ngsl:0992","ngsl:1051","ngsl:0979","ngsl:1775","ngsl:1804","ngsl:1818"]},
];
